(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("archilochus-fragments-e",[{"st": "—", "sp": "HDR", "t": "ΑΡΧΙΛΟΧΟΥ ΑΠΟΣΠΑΣΜΑΤΑ"}, {"st": "—", "sp": "HDR", "t": "Fragments Concerning Archilochus’ Life"}, {"st": "—", "sp": "N", "t": "“εἶδον γὰρ ἑκὰς ἐὼν τὰ πόλλ᾽ ἐν ἀμαχανίᾳ<br>ψογερὸν Ἀρχίλοχον βαρυλόγοις ἔχθεσιν<br>πιαινόμενον.<br>Pind. P. 2. 99"}, {"st": "—", "sp": "N", "t": "“ ... Γύγης, τοῦ καὶ Ἀρχίλοχος ὁ Πάριος κατὰ τὸν αὐτὸν χρόνον γενόμενος ἐν ἰάμβῳ τριμέτρῳ ἐπεμνήσθη.” <em>Hdt. i. 12<\/em>"}, {"st": "—", "sp": "N", "t": "“ἀφ᾽ οὗ Ἀρχίλοχος ὁ ἰαμβοποιὸς ἐφάνη ἔτη ΗΗΗΗΔΓΙΙΙ ἄρχοντος Ἀθήνησι Λυσιάδου.” <em>Marm. Par. 33<\/em>"}, {"st": "—", "sp": "N", "t": "“π. Ὁμήρου: Ἀρίσταρχος δὲ ἐν τοῖς Ἀρχιλοχείοις Ὑπομνήμασι κατὰ τὴν Ἰωνικὴν ἀποικίαν φησὶ φέρεσθαι αὐτόν.” <em>Clem. Al. Str. i. 21. 141S<\/em>"}, {"st": "—", "sp": "N", "t": "“π. γραφὰς τὰς τῆς ἐν Δελφοῖς λέσχης: οἱ δὲ ἐπιβεβηκότες τῆς νεὼς οὐκ ἐπιφανεῖς ἐς ἅπαν εἰσὶν οἷς προσήκουσι. Τέλλις μὲν ἡλικίαν ἐφήβου γεγονὼς φαίνεται, Κλεόβοια δὲ ἔτι παρθένος, ἔχει δὲ ἐν τοῖς γόνασι κιβωτόν, ὁποίας ποιεῖσθαι νομίζουσι Δήμητρι: ἐς μὲν δὴ τὸν Τέλλιν τοσοῦτον ἤκουσα, ὡς ὁ ποιητὴς Ἀρχίλοχος ἀπόγονος εἴη τρίτος Τέλλιδος: Κλεόβοιαν δὲ ἐς Θάσον τὰ ὄργια τῆς Δήμητρος ἐνεγκεῖν πρώτην ἐκ Πάρου φασίν.” <em>Paus. 10. 28. 3<\/em>"}, {"st": "—", "sp": "N", "t": "“Θάσος: ... ὅτι δὲ καὶ ἀερία ἡ Θάσος δῆλον ἐκ τοῦ χρησμοῦ τοῦ δοθέντος πατρὶ τοῦ Ἀρχιλόχου:<br>ἄγγειλον Παρίοις, Τελεσίκλειε, ὥς σε κελεύω<br>νήσῳ ἐν ἠερίῃ κτίζειν εὐδείελον ἄστυ.” <em>Steph. Byz.<\/em>"}, {"st": "—", "sp": "N", "t": "“ὡς ὁ Κρατῖνος ἐν Τοῖς Ἀρχιλόχοις ἔφη.” <em>Ath. 4. 164 e<\/em><br>“ἴαμβον ἐπενόησεν Ἀρχίλοχος ὁ Πάριος.” <em>Clem. Al. Str. 133S<\/em><br><em>Clem. Al. Str. 144S.<\/em>"}, {"st": "—", "sp": "N", "t": "“... τοῦ μεθυπλῆγος<br>φροίμιον Ἀρχιλόχου.<br><em>Callim. fr. 233 p. 466 Schneider<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχίλοχον πατεῖς: ἐπὶ τῶν λοιδορούντων: τοιοῦτος γὰρ ὁ Ἀρχίλοχος.” <em>Diogen. 2. 95<\/em>"}, {"st": "—", "sp": "N", "t": "“ Cave, cave; namque in malos asperrimus<br>parata tollo cornua,<br>qualis Lycambae spretus infido gener<br>aut acer hostis Bupalo.”<br><em>Hor. Epod. 6. 13<\/em><br>“αρξηιλοξηυμ σιγνιφιξατ, θυι λψξαμβεν προβροσις ϝερσιβυς υσθυε εο ινσεξτατυς εστ, υτ ιλλε μορτεμ σιβι ξονσξισξερετ. ηοξ αυτεμ εο φεξιτ, θυοδ ιλλε φιλιαμ συαμ ιν ματριμονιυμ προμισσαμ μοχ δενεγασσετ.” <em>Sch. ad Hor. Epod. 6. 13<\/em>"}, {"st": "—", "sp": "N", "t": "“ Parios ego primus iambos<br>ostendi Latio, numeros animosque secutus<br>Archilochi, non res et agentia verba Lycamben.<br>ac ne me foliis ideo brevioribus ornes,<br>quod timui mutare modos et carminis artem,<br>temperat Archilochi Musam pede mascula Sappho,<br>temperat Alcaeus, sed rebus et ordine dispar,<br>nec socerum quaerit quem versibus oblinat atris,<br>nec sponsae laqueum famoso carmine nectit.”<br><em>Hor. Ep. i. 19. 23<\/em>"}, {"st": "—", "sp": "N", "t": "“ Archilochum proprio rabies armavit iambo.”<br><em>Hor. A.P. 79<\/em>"}, {"st": "—", "sp": "N", "t": "“ postmodo, si perges, in te mihi liber iambus<br>tincta Lycambeo sanguine tela dabit.”<br><em>Ovid. Ib. 53<\/em>"}, {"st": "—", "sp": "N", "t": "“ἰστέον δὲ ὅτι πολλῶν προσώπων ἁψαμένων βρόχους ἐπὶ λύπαις ἔπαθον οὕτω κατὰ τὴν παλαιὰν ἱστορίαν καὶ αἱ Λυκαμβίδες,3 ἐπὶ τοῖς Ἀρχιλόχου ποιήμασι μὴ φέρουσαι τὴν ἐπιφορὰν τῶν ἐκείνου σκωμμάτων.” <em>Eust. in Od. 1684. 45<\/em>"}, {"st": "—", "sp": "N", "t": "“Lacedaemonii libros Archilochi e civitate sua exportare iusserunt, quod eorum parum verecundam ac pudicam lectionem arbitrabantur; noluerunt enim ea liberorum suorum animos imbui, ne plus moribus noceret quam ingeniis prodesset.” <em>Val. Max. 6. 3. Ext. 1<\/em>"}, {"st": "—", "sp": "N", "t": "“ἔτι δέ, καθάπερ Πίνδαρός φησι, καὶ τῶν σκολιῶν μελῶν Τέρπανδρος εὑρετὴς ἦν: ἀλλὰ μὴν καὶ Ἀρχίλοχος τὴν τῶν τριμέτρων ῥυθμοποιΐαν προσεξεῦρε καὶ τὴν εἰς τοὺς οὐχ ὁμογενεῖς ῥυθμοὺς ἔντασιν καὶ τὴν παρακαταλογὴν καὶ τὴν περὶ ταῦτα κροῦσιν: πρώτῳ δ᾽ αὐτῷ τά τ᾽ ἐπῳδὰ καὶ τὰ τετράμετρα καὶ τὸ κρητικὸν καὶ τὸ προσοδιακὸν ἀποδέδοται καὶ ἡ τοῦ ἡρῴου αὔξησις, ὑπ᾽ ἐνίων δὲ καὶ τὸ ἐλεγεῖον, πρὸς δὲ τούτοις ἥ τε τοῦ ἰαμβείου πρὸς τὸν ἐπιβατὸν παιῶνα ἔντασις καὶ ἡ τοῦ ηὐξημένου ἡρῴου εἴς τε τὸ προσοδιακὸν καὶ τὸ κρητικόν: ἔτι δὲ τῶν ἰαμβείων τὸ τὰ μὲν λέγεσθαι παρὰ τὴν κροῦσιν τὰ δ᾽ ᾁδεσθαι, Ἀρχίλοχόν φασι καταδεῖξαι, εἶθ᾽ οὕτω χρήσασθαι τοὺς τραγικοὺς ποιητάς, Κρέξον δὲ λαβόντα εἰς διθυράμβων χρῆσιν ἀγαγεῖν. οἴονται δὲ καὶ τὴν κροῦσιν τὴν ὑπὸ τὴν ᾠδὴν τοῦτον πρῶτον εὑρεῖν, τοὺς δ᾽ ἀρχαίους πάντας πρόσχορδα κρούειν.” <em>Plut. Mus. 28<\/em>"}, {"st": "—", "sp": "N", "t": "<em>Ath. 14. 620 c.<\/em>"}, {"st": "—", "sp": "N", "t": "“Κλέαρχος δ᾽ ἐν τῷ προτέρῳ Περὶ Γρίφων ‘τὰ Ἀρχιλόχου’ φησίν ‘Σιμωνίδης ὁ Ζακύνθιος ἐν τοῖς θεάτροις ἐπὶ δίφρου καθήμενος ἐρραψώδει.’” <em>Ath. 14. 620 c.<\/em>"}, {"st": "—", "sp": "N", "t": "“quod si uno pede brevius quam nunc est fuerit, erit ithyphallicum metrum, inventum ab Archilocho, e tribustrochaeis coniunctis, ut Bacche plaude Bacche , quodin honorem eiusdem dei poetae compositum protulerunt.” <em>Mar. Vict. Gr. Lat. 6. 1. p. 85 K:<\/em>"}, {"st": "—", "sp": "N", "t": "“dimetrus quoque quod Archilochius vocatur beatus ille qui procul .” <em>Mar. Vict. Gr. Lat. 6. 1. p. 81 de iambico:<\/em>"}, {"st": "—", "sp": "N", "t": "“nam perfecto poetae levia et sonora sectanda sunt; quae autem fragosa et aspera, dicis causa, non ut imitentur, sed ut vitentur, noscenda sunt. quorum, sicut et aliorum complurium, auctor et parens fertur Archilochus, singularis artificii in excogitandis ac formandis novis metris, qui primus epodos excitavit alios breviores, alios longiores, detrahens unum pedem seu colum metro, ut illi subiceret id quod ex ipso detractum esse videbatur; ut in heroo, a quo primum coepit, tanquam diffugere nives, redeunt iam gramina campis ; dehinc epodus suigeneris, arboribusque comae .” <em>Mar. Vict. Gr. Lat. 6. 1. p. 104<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχίλοχοντὸν ποιητὴν Κόραξ ὄνομα ἔκτεινε, πρὸς ὅν φασιν εἰπεῖν τὴν Πυθίαν ‘ἔξιθι νηοῦ,’ τοῦτον δ᾽ εἰπεῖν ‘ἀλλὰ καθαρός εἰμι, ἄναξ: ἐν χειρῶν γὰρ νόμῳ ἔκτεινα.’” <em>Heracleides Pol. 8 <\/em>(<em>F.H.G. 2. 214<\/em>)"}, {"st": "—", "sp": "N", "t": "“(π. Κόρακος τοῦ Ναξίου): ὁ γὰρ ἀποκτείνας ἐν τῇ μάχῃ τὸν Ἀρχίλοχον ἐκαλεῖτο Καλλώνδης, ὡς ἔοικεν, ἦν δ᾽ αὐτῷ Κόραξ ἐπωνύμιον. ἐπιβληθεὶς δὲ τὸ πρῶτον ὑπὸ τῆς Πυθίας ὡς ἱερὸν ἄνδρα τῶν Μουσῶν ἀνῃρηκώς, εἶτα χρησάμενος λιταῖς τισι καὶ προστροπαῖς μετὰ δικαιολογίας ἐκελεύσθη πορευθεὶς ἐπὶ τὴν τοῦ τέττιγος οἴκησιν ἱλάσασθαι τὴν τοῦ Ἀρχιλόχου ψυχήν: τοῦτο δ᾽ ἦν ὁ Ταίναρος: ἐκεῖ γάρ φασιν ἐλθόντα μετὰ στόλου Τέττιγα τὸν Κρῆτα πόλιν κτίσαι καὶ κατοικῆσαι παρὰ τὸ ψυχοπομπεῖον.” <em>Plut. Sera Num. Vind. 17<\/em>"}, {"st": "—", "sp": "N", "t": "“π. Ἀρχιλόχου: τόν μέν γ᾽ ἀποκτείναντα αὐτὸν ὁ Ἀπόλλων ἐξελαύνων ἐκ τοῦ νεὼ Μουσῶν αὐτὸν ἀνεῖπε θεράποντα ἀνῃρηκέναι, καὶ τὸ δεύτερον ὡς ἀπελογεῖτο ἐν πολέμῳ λέγων ἀποκεῖναι πάλιν Μουσῶν θεράποντα ἔφη τὸν Ἀρχίλοχον: τῷ πατρὶ δὲ αὐτοῦ χρωμένῳ πρὸ τῆς γενέσεως ἀθάνατόν οἱ παῖδα γενήσεσθαι προεῖπεν.4” <em>Dio Chrys. 33. p. 397 M<\/em>"}, {"st": "—", "sp": "N", "t": "“Πάριοι γοῦν Ἀρχίλοχον καίπερ βλάσφημον ὄντα τετιμήκασιν.” <em>Arist. Rh. 1398b<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἕρμιππος δὲ ἐν τῷ Περὶ Γοργίου ῾ὡς ἐπεδήμησἐ φησί ῾ταῖς Ἀθήναις Γοργίας μετὰ τὸ ποιήσασθαι τὴν ἀνάθεσιν τῆς ἐν Δελφοῖς ἑαυτοῦ χρυσῆς εἰκόνος, εἰπόντος τοῦ Πλάτωνος ὅτε εἶδεν αὐτόν ‘ἥκει ἡμῖν ὁ καλός τε καὶ χρυσοῦς Γοργίας,’ ἔφη ὁ Γοργίας ‘ἦ καλόν γε αἱ Ἀθῆναι νέον τοῦτον Ἀρχίλοχον ἐνηνόχασιν.’” <em>Ath. 11. 505e<\/em>"}, {"st": "—", "sp": "N", "t": "“ἐν δὲ καὶ ἐκ φοβερῆς σκολιότριχος ἄνθος ἀκάνθης<br>Ἀρχιλόχου, μικρὰς στράγγας ἀπ᾽ ὠκεανοῦ.” 5 “ <em>Mel. A.P.4.1<\/em>"}, {"st": "—", "sp": "N", "t": "“sed quaero num existimes, non dico Homerum, Archilochum, Pindarum, sed Phidiam, Polycletum, Zeuxin, ad voluptatem artes suas direxisse?” <em>Cic. Fin.2. 114<\/em>"}, {"st": "—", "sp": "N", "t": "“quod vereris ne ἀδόλεσχος, mihi tu? quis minus? cui ut Aristophani Archilochi iambus, sic epistola longissima quaeque optima videtur.” <em>Cic. Att. 16. 11. 2<\/em>"}, {"st": "—", "sp": "N", "t": "“comitia Bibulus cum Archilochio edicto in ante diem xv Kal. Novembr. distulit.” <em>Cic. Att. 2.20.6<\/em>"}, {"st": "—", "sp": "N", "t": "“itaque ex tribus receptis Aristarchi iudicio scriptoribus iamborum ad ἕξιν maxime pertinebit Archilochus. summa in hoc vis elocutionis, cum validae tum breves vibrantesque sententiae, plurimum sanguinis atque nervorum, adeo ut videatur quibusdam, quod quoquam minor est, materiae esse non ingenii vitium.” <em>Quint. 10. 1. 59<\/em>"}, {"st": "—", "sp": "N", "t": "“μὄνος Ἡρόδοτος Ὁμηρικώτατος ἐγένετο; Στησίχορος ἔτι πρότερον ὅ τε Ἀρχίλοχος ... “ <em>Longin. Subl. 13. 3<\/em>"}, {"st": "—", "sp": "N", "t": "“ἆρ᾽ οὖν Ἀπολλώνιος ἂν μᾶλλον ἢ Ὅμηρος ἐθέλοις γενέσθαι; τί δέ; Ἐρατοσθένης ἐν τῇ Ἠριγόνῃ (διὰ πάντων γὰρ ἀμώμητον τὸ ποημάτιον) Ἀρχιλόχου, πολλὰ καὶ ἀνοικονόμητα παρασύροντος κἀκεῖνα ἐκ τῆς ἐμβολῆς6 τοῦ δαιμονίου πνεύματος ἣν ὑπὸ νόμον τάξαι δύσκολον, ἆρα δὴ μείζων ποιητής;” <em>Longin. Subl. 33.4 ...<\/em>"}, {"st": "—", "sp": "N", "t": "“εἵλκυσαν ἐντεῦθεν (ἀπὸ τοῦ μύθου) οἱ ποιηταὶ τὸν αἶνον ... ὁ δὲ μετὰ τοῦτον (Ἡσίοδον) Ἀρχίλοχος ὥσπερ ἥδυσμά τι περιτιθεὶς τῇ ποιήσει μύθοις οὐκ ὀλιγάκις ἐχρήσατο.” <em>Jul. Or. 7. 207a<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... Ἀπολλώνιος ὁ Ῥόδιος ἐν τῷ Περὶ Ἀρχιλόχου.” <em>Ath. 10. 451d<\/em>"}, {"st": "—", "sp": "N", "t": "“ὁ δὲ Κάτων σφόδρα παροξυνθεὶς καὶ διακαεὶς ἐπεχείρησε μὲν ἐπεξελθεῖν διὰ δίκης, ὡς δὲ οἱ φίλοι τοῦτο ἐκωλυσαν, ὀργῇ καὶ νεότητι τρέψας ἑαυτὸν εἰς ἰάμβους πολλὰ τὸν Σκηπίωνα καθύβρισε, τῷ πικρῷ προσχρησάμενος τοῦ Ἀρχιλόχου, τὸ δὲ ἀκόλαστον ἀφεὶς καὶ παιδαριῶδες.” <em>Plut. Cat. 7<\/em>"}, {"st": "—", "sp": "N", "t": "“Λεωνίδου:” Ἀρχίλοχον καὶ στᾶθι καὶ εἴσιδε τὸν πάλαι ποιητὰν<br>τὸν τῶν ἰάμβων, οὗ τὸ μύριον κλέος<br>διῆλθε κἠπὶ νύκτα καὶ ποτ᾽ ἀῶ.<br>ἦ ῥά νιν αἱ Μοῖσαι καὶ ὁ Δάλιος ἠγάπευν Ἀπόλλων,<br>ὡς ἐμμελής τ᾽ ἐγένετο κἠπιδέξιος<br>ἔπεά τε ποιεῖν πρὸς λύραν τ᾽ ἀείδειν.”8” <em>A.P. 7. 664<\/em>"}, {"st": "—", "sp": "N", "t": "“Γαιτουλικοῦ:” σῆμα τόδ᾽ Ἀρχιλόχου παραπόντιον, ὅς ποτεπικρὴν<br>μοῦσαν ἐχιδναίῳ πρῶτος ἔβαψε χόλῳ,<br>αἱμάξας Ἑλικῶνα τὸν ἥμερον: οἶδε Λυκάμβης,<br>μυρόμενος τρισσῶν ἅμματα θυγατέρων:<br>ἠρέμα δὴ παράμειψον, ὁδοιπόρε, μή ποτε τοῦδε<br>κινήσῃς τύμβῳ σφῆκας ἐφεζόμενους.”9” <em>A.P. 7. 71<\/em>"}, {"st": "—", "sp": "HDR", "t": "Elegiac Poems"}, {"st": "—", "sp": "N", "t": "“ἀλλ᾽ οἱ παλαιοὶ τὴν ἀνδρείαν ὑπελάμβανον εἶναι μεγίστην τῶν πολιτικῶν ἀρετῶν ... Ἀρχίλοχος γοῦν ἀγαθὸς ὦν ποιητὴς πρῶτον ἐκαυχήσατο τὸ δύνασθαι μετέχειν τῶν πολιτικῶν ἀγώνων, δεύτερον δ᾽ ἐμνήσθη τῶν περὶ τὴν ποιητικὴν ὑπαρχόντων αὐτῷ, λέγων:<br>εἰμὶ δ᾽ ἐγὼ θεράπων μὲν Ἐνυαλίοιο ἄνακτος,<br>καὶ Μουσέων ἐρατὸν δῶρον ἐπιστάμενος.<br><em>Ath. 14. 627c<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχίλοχος τὸν Νάξιον οἶνον τῷ νέκταρι παραβάλλει: ὅς καί πού φησιν:<br>ἐν δορὶ μὲν μοι μᾶζα μεμαγμένη, ἐν δορὶ δ᾽ οἶνος<br>Ἰσμαρικός, πίνω δ᾽ ἐν δορὶ κεκλιμένος.<br><em>Ath. 1. 30f<\/em>"}, {"st": "—", "sp": "N", "t": "“οἱ δὲ Ἄβαντες ἐκείραντο πρῶτοι τὸν τρόπον τοῦτον, οὐχ ὑπ᾽ Ἀράβων διδαχθέντες, ὡς ἔνιοι νομίζουσιν, οὺδὲ Μυσοὺς ζηλώσαντες, ἀλλ᾽ ὄντες πολεμικοὶ καὶ ἀγχέμαχοι καὶ μάλιστα δὴ πάντων εἰς χεῖρας ὠθεῖσθαι τοῖς ἐναντίοις μεμαθηκότες, ὡς μαρτυρεῖ καὶ Ἀρχίλοχος ἐν τούτοις:<br>οὔ τοι πόλλ᾽ ἐπὶ τόξα τανύσσεται οὐδὲ θαμειαὶ<br>σφενδόναι, εὖτ᾽ ἂν δὴ μῶλον Ἄρης συνάγῃ<br>ἐν πεδίῳ: ξιφέων δὲ πολύστονον ἔσσεται ἔργον:<br>ταύτης γὰρ κεῖνοι δαίμονές εἰσι μάχης<br>δεσπόται Εὐβοίης δουρικλυτοί.<br>οὖν μὴ παρέχοιεν ἐκ τῶν τριχῶν ἀντίληψιν τοῖς πολεμίοις ἀπεκείραντο.”<br><em>Plut. Vit. Thes. 5<\/em>"}, {"st": "—", "sp": "N", "t": "“κώθων Λακωνικὸν ποτήριον ... μνημονεύει αἰτοῦ καὶ Ἀρχίλοχος ἐν Ἐλεγείοις ὡς ποτηρίου οὕτως:<br>ἀλλ᾽ ἄγε, σὺν κώθωνι θοῆς διὰ σέλματα νηὸς<br>φοίτα καὶ κοΐλων πώματ᾽ ἄφελκε κάδων,<br>ἄγρει δ᾽ οἶνον ἐρυθρὸν ἀπὸ τρυγός: οὐδὲ γὰρ ἡμεῖς<br>νήφειν ἐν φυλακῇ τῇδε δυνησόμεθα.<br><em>Ath. 11 483b<\/em>"}, {"st": "—", "sp": "N", "t": "“παρέξ: μετὰ γοῦν τῆς διά οὖσα ἡ ἐξ οὐ τρέπει τὸ ξ:<br>διὲξ σωλῆνος ἐς ἄγγος<br><em>Sch. Il. 9.7<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχίλοχον τὸν ποιητὴν ἐν Λακεδαίμονι γενόμενον αὐτῦς ὥρας ἐδίωξαν, διότι ἐπέγνωσαν αὐτὸν πεποιηκότα ὡς κρεῖττόν ἐστιν ἀποβαλεῖν τὰ ὅπλα ἢ ἀποθανεῖν:<br>ἀσπίδι μὲν Σαΐων τις ἀγάλλεται, ἣν παρὰ θάμνῳ<br>ἔντος ἀμώμητον κάλλιπον οὐκ ἐθέλων:<br>αὐτὸν δ᾽ ἔκ μ᾽ ἐσάωσα: τί μοι μέλει ἀσπὶς ἐκεινη;<br>ἐρρέτω: ἐξαῦτις κτήσομαι οὐ κακίω.<br><em>Plut. Lac. Inst.<\/em>"}, {"st": "—", "sp": "N", "t": "“ὃν φοίνιος Ἄρης οὐκ ἐξένισεν: ξένια γὰρ Άρεως τραύματα καὶ φόνοι. καὶ Ἀρχίλοχος:<br>ξείνια δυσμενέσιν λυγρὰ χαριζόμενος<br><em>Sch. Soph. El. 96<\/em>"}, {"st": "—", "sp": "N", "t": "“ἐπίρρητις: ὁ ψόγος καὶ ἡ κακηγορία. ἔνθεν λοιπὸν καὶ ἐπίρρητος. Ἀρχίλοχος ἐν Ἐλεγείοις:<br>Αἰσιμίδη, δήμου μὲν ἐπίρρησιν μελεδαίνων<br>οὐδεὶς ἂν μάλα πόλλ᾽ ἱμερόεντα πάθοι.<br><em>Orion 55. 22<\/em>"}, {"st": "—", "sp": "N", "t": "“παρηγορικά: Ἀρχιλόχου:<br>κήδεα μὲν στονόεντα, Περίκλεες, οὔτε τις ἀστῶν<br>μεμφόμενος θαλίῃς τέρψεται οὔτε πόλις:<br>τοίους γὰρ κατὰ κῦμα πολυφλοίσβοιο θαλάσσης<br>ἔκλυσεν, οἰδαλέους δ᾽ ἀμφ᾽ ὀδύνῃς ἔχομεν<br>πνεύμονας: ἀλλὰ θεοὶ γὰρ ἀνηκέστοισι κακοῖσιν,<br>ὦ φίλ᾽, ἐπὶ κρατερὴν τλημοσύνην ἔθεσαν<br>φάρμακον: ἄλλοτε δ᾽ ἄλλον ἔχει τάδε: νῦν μὲν ἐς ἡμέας<br>ἐτράπεθ᾽, αἱματόεν δ᾽ ἕλκος ἀναστένομεν,<br>ἐξαῦτις δ᾽ ἑτέρους ἐπαμείψεται: ἀλλὰ τάχιστα<br>τλῆτε γυναικεῖον πένθος ἀπωσάμενοι.<br><em>Stob. Fl 124. 30<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ δὲ δωρεὰν ἐπὶ σαμφορᾶς λαμβάνεται καὶ ἐπὶ κακοῦ. ὡς καὶ Ἀρχίλοχος:<br>κρύπτωμεν δ᾽ ἀνιηρὰ Ποσειδάωνος ἄνακτος δῶρα.<br><em>Sch. Aesch. P.V. 616<\/em>"}, {"st": "—", "sp": "N", "t": "“θεσσάμενοι παίδων γένος: θεσσάμενοι, ἐξ αἰτήσεως ἀναλαβόντες, αἰτήσαντες: καὶ Ἀρχίλοχος:<br>Παλλάδ᾽ ἐϋπλόκαμον πολιῆς ἁλὸς ἐν πελάγεσσι<br>θεσσάμενοι γλυκερὸν νόστον<br><em>Sch. Ap. Rh. i. 824<\/em>"}, {"st": "—", "sp": "N", "t": "“οἷον εὐθὺς ὁ Ἀρχίλοχος, ὅταν μὲν εὐχόμενος λέγῃ: <em>fr. 75<\/em> αὐτὸν θὲον ἐπικαλούμενος δῆλός ἐστιν: ὅταν δὲ τὸν ἄνδρα τῆς ἀδελφῆς ἠθανισμένον ἐν θαλάττῃ καὶ μὴ τυχόντα νομὶμου ταφῆς θρηνῶν λέγῃ μετριώτερον ἂν τὴν συμφορὰν ἐνεγκεῖν,<br>εἰ κείνου κεφαλὴν καὶ χαρίεντα μέλεα<br>Ἥφαιστος καθαροῖσιν ἐν εἵμασιν ἀμφεπονήθη"}, {"st": "—", "sp": "N", "t": "τὸ πῦρ οὕτως οὐ τὸν θεὸν προσηγόρευσεν.”<br><em>Plut. Aud. Poet. 6. 23a<\/em>"}, {"st": "—", "sp": "N", "t": "“πάλιν ὁ Ἀρχίλοχος οὐκ ἐπαινεῖται λυπούμενος μὲν ἐπὶ τῷ ἀνδρὶ τῆς ἀδελφῆς διεφθαρμένῳ κατὰ θάλατταν, οἴνῳ δὲ καὶ παιδιᾷ πρὸς τὴν λύπην μάχεσθαι διανοούμενος: αἰτίαν μέντοι λόγον ἔχουσαν εἴρηκεν:<br>οὔτε τι γὰρ κλαίων ἰήσομαι οὔτε κάκιον<br>θήσω τερπωλὰς καὶ θαλίας ἐφέπων."}, {"st": "—", "sp": "N", "t": "εἰ γὰρ ἐκεῖνος οὐδὲν ἐνόμιζεν ποιήσειν κάκιον τερπωλὰς καὶ θαλίας ἐφέπων, πῶς ἡμῖν τὰ παρόντα χεῖρον ἕξει φιλοτοφοῦσι κτλ.”<br><em>Plut. Aud. Poet. 12. 33 b<\/em>"}, {"st": "—", "sp": "N", "t": "“τούτων ἡ μὲν διὰ τὸ χρήσιμόν ἐστιν ἡ τῶν πλείστων φιλία: διὰ γὰρ τὸ χρησίμους εἶναι φιλοῦσιν ἀλλήλους καὶ μέχρι τούτου, ὥσπερ ἡ παροιμία:<br>γλαῦκ᾽, ἐπίκουρος ἀνὴρ τόσσον φίλος ἕστε μάχηται.<br><em>Arist. Eud. Eth. 1236a. 33<\/em>"}, {"st": "—", "sp": "N", "t": "“πάντα γὰρ πόνος τεύχει θνητοῖς, κατ᾽ Ἀρχίλοχον, μελέτη τ᾽ ἀρίστη.<br>πάντα πόνος τεύχει θνητοῖς μελέτη τε βροτείη.<br><em>Joan. Sic. Rhet. Gr. W. 6. 96<\/em>"}, {"st": "—", "sp": "N", "t": "“π. τύχης ἢ ταὐτομάτου:<br>πάντα τύχη καὶ μοῖρα, Περίκλεες, ἀνδρὶ δίδωσιν.<br><em>Stob. Ecl. i. 6. 3<\/em>"}, {"st": "—", "sp": "N", "t": "“π. Πλαγγόνος καὶ Βακχίδος: καὶ τοῦ λοιποῦ φίλαι ἐγένοντο, κοινῶς περιεπουσαι τὸν ἐραστήν. ἐφ᾽ οἷς Ἴωνες ἀγασθέντες, ὥς φησι Μενέτωρ ἐν τῷ Περὶ Ἀναθηοάτων, Πασιφίλαν ἐκάλεσαν τὴν Πλαγγόνα. μαρτυρεῖ δὲ καὶ Ἀρχίλοχος περὶ αὐτῆς ἐν τούτοις:<br>συκῆ πετραίη πολλὰς βόσκουσα κορώνας<br>εὐήθης ξείνων δέκτρια Πασιφίλη.<br><em>Ath. 13. 594c<\/em>"}, {"st": "—", "sp": "HDR", "t": "Epigrams"}, {"st": "—", "sp": "N", "t": "“Ἀρχιλόχου:<br>ὑψηλοὺς Μεγάτιμον Ἀριστοφόωντά τε Νάξου<br>κίονας, ὦ μεγάλη γαἶ, ὑπένερθεν ἔχεις.<br><em>Anth. Pal. 7. 441<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχιλόχου:<br>Ἀλκιβίη πλοκάμων ἱερὴν ἀνέθηκε καλύπτρην<br>Ἥρῃ κουριδίων εὖτ᾽ ἐκύρησε γάμων."}, {"st": "—", "sp": "HDR", "t": "Iambi Trimeters"}, {"st": "—", "sp": "N", "t": "“π. Μαγνήτων: Ἀρχίλοχος δὲ ἤδη φαίνεται γνωρίζων τὴν γενομένην αὐτοῖς συμφοράν:<br>κλαίω τὰ Θασίων, οὐ τὰ Μαγνήτων κακά.<br><em>Str. 14. 647<\/em>"}, {"st": "—", "sp": "N", "t": "“καθάπερ Ἀρχίλοχος τῆς Θάσου τὰ καρποφόρα καὶ οἰνόπεδα παρορῶν διὰ τὸ τραχὺ καὶ ἀνώμαλον διέβαλε τὴν νῆσον εἰπών:<br>ἥδε δ᾽ ὥστ᾽ ὄνου ῥάχις<br>ἕστηκεν ὕης ἀγρίης ἐπιστεφής:"}, {"st": "—", "sp": "N", "t": "οὕτω τῆς φυγῆς πρὸς ἓν μέρος τὸ ἄδοξον ἐντεινόμενοι παρορῶμεν τὴν ἀπραγμοσύνην καὶ τὴν σχολὴν καὶ τὴν ἐλευθερίαν.”<br><em>Plut. Exil. 12<\/em>"}, {"st": "—", "sp": "N", "t": "“καὶ Ἀρχίλοχος δ᾽ ὁ ποιητὴς ὑπερτεθαύμακε τὴν χώραν τῶν Σιριτῶν διὰ τὴν εὐδαιμονίαν: περὶ γοῦν τῆς Θάσου λέγων ὡς ἥσσονός φησιν:<br>οὐ γάρ τι καλὸς χῶρος οὐδ᾽ ἐπίμερος<br>οὐδ᾽ ἐρατός, οἷος ἀμφὶ Σίριος ῥοάς.<br><em>Ath. 12. 523b<\/em>"}, {"st": "—", "sp": "N", "t": "“καὶ τότε καὶ βραχύχρονος εἶναι τῷ βίῳ μέλλων ι ποιεῖ ὅπερ καὶ ὕστερον Ἀρχίλοχος ἐκεῖνος: ι σφῆς ἀδελφῆς γὰρ σύζυγον πνιγέντα τῇ θαλάσῃ ι περιπαθῶς ὠδύρετο γράφειν μὴ θέλων ὅλως, ι λέγων πρὸς τοὺς βιάζοντας συγγράμμασιν ἐγκύπτειν: ι<br>καί μ᾽ οὔτ᾽ ἰάμβων οὔτε τερπωλέων μέλει:"}, {"st": "—", "sp": "N", "t": "ὡς δὲ δακρύων κέκμηκε μάτην, εἰρήκει τάδε:(<em>fr. 13<\/em>)”<br><em>Tzetz. ap. Matr. An. 216<\/em>"}, {"st": "—", "sp": "N", "t": "“κυμάτων ἐν ἀγκάλαις: δίδυμός φησι παρὰ τῷ Αἰσχύλῳ, ἔστι δὲ ὄντως παρὰ Ἀρχιλόχῳ:<br>ψυχὰς ἔχοντες κυμάτων ἐν ἀγκάλαις<br><em>Sch. Ar. Ran. 704<\/em>"}, {"st": "—", "sp": "N", "t": "“[σκοπεῖν χρὴ μὴ οὐκ ἐν τῷ Καρὶ ὑμῖν ὁ κίνδυνος κινδυνεύηται, ἀλλ᾽ ἐν τοῖς ὑέσιͅ: ἐπὶ τῶν ἐπισφαλέστερον καὶ ἐν ἀλλοτρίοις κινδυνευόντων. Κᾶρες γὰρ δοκοῦσι πρῶτον μισθοφορῆσαι ... μέμνηται δ᾽ αὐτῆς Ἀρχίλοχος λέγων:<br>καὶ δὴ π᾽ίκουρος ὥστε Κὰρ κεκλήσομαι.<br><em>Sch. Plat. Lach. 187 b<\/em>"}, {"st": "—", "sp": "N", "t": "“εἰς δὲ τὸ ἦθος, ἐπεὶ ἔνια περὶ αὑτοῦ λέγειν ἢ ἐπίφθονον ἢ μακρολογίαν ἢ ἀντιλογίαν ἔχει, καὶ περὶ ἄλλου ἢ λοιδορίαν ἢ ἀγροικίαν, ἕτερον χρὴ λέγοντα ποιεῖν, ὅπερ Ἰσοκράτης ποιεῖ ἐν Τῷ Φιλίππῳ καὶ Ἀντιδόσει: καὶ ὡς Ἀρχίλοχος ψέγει: ποιεῖ γὰρ . . λέγοντα:(<em>fr. 74<\/em>) ... καὶ τὸν Χάρωνα τὸν τέκτονα ἐν τῷ ἰάμβῳ οὗ ἡ ἀρχή:<br>οὔ μοι τὰ Γύγ εω τοῦ πολυχρύσου μέλει,<br>οὐδ᾽ εἷλέ πώ με ζῆλος, οὐδ᾽ ἀγαίομαι<br>θ εῶ ν ἔργα, μεγάλης δ᾽ οὐκ ἐρέω τυραννίδος:<br>ἀπόπροθεν γάρ ἐστιν ὀφθαλμῶν ἐμῶν.<br><em>Arist. Rh. 1418.42b<\/em>"}, {"st": "—", "sp": "N", "t": "“καρτερεῖν: ἀντὶ τοῦ κρατεῖν καὶ ἀντέχειν: καὶ τὸν ἐγκρατῆ λέγουσι καρτερόν: Ἀρχίλοχος:<br>ὁ δ᾽ Ἀσίης καρτερὸς μηλοτρόφου.<br><em>Sch. Eur. Med. 708<\/em>"}, {"st": "—", "sp": "N", "t": "“Alii cognominatum Apollinem putant ὡς ἀπολλύντα τὰ ζῷα : exanimat enim et perimit animantes cum pestem intemperie immittit; ut Euripides ... item Archilochus:<br>a)/nac *)/apollon, kai\\ su\\ tou\\s me<br> ai)ti/ous1<br>sh/maine kai/ sf ea s o)/llu’ w(/sper o)llu/eis.<br><em>Macr. Sat. i. 17<\/em>"}, {"st": "—", "sp": "N", "t": "“ἡ διπλῆ ὅτι Ἀρχίλοχος ὑπερτέραν τὴν νεωτέραν ἐδέξατο:<br>οἴην Λυκάμβ εω παῖδα τὴν ὑπερτέρην.<br><em>Sch. Il. 11. 786<\/em>"}, {"st": "—", "sp": "N", "t": "“καὶ ὁ κάλλιστος ποιητῶν Ἀρχίλοχος ἐπαινέσας αὐτὴν (τὴν κόμην) ἐπαινεῖ μὲν οὖσαν ἐν ἑταίρας σώματι, λέγει δὲ οὕτως: ‘ἡ δέ οἱ ... μετάφρενα.’<br>ἔχουσα θαλλὸν μυρσίνης ἐτέρπετο<br>ῥοδῆς τε καλὸν ἄνθος, ἡ δέ οἱ κόμη<br>ὤμους κατεσκίαζε καὶ μετάφρενα.<br><em>Synes. Laud. Calv. 75b<\/em> “ῥόδον καὶ ῥοδωνιὰ καὶ ῥοδῆ διαφέρει: ῥόδον μὲν γὰρ τὸ ἄνθος, ῥοδωνιὰ δὲ ὁ τόπος, ῥοδῆ δὲ τὸ φυτόν. Ἀρχίλοχος:” <em>Ammon. 123<\/em>"}, {"st": "—", "sp": "N", "t": "“π. μύρου: καὶ ἀλλαχοῦ δ᾽ (Ἀρχίλοχος) ἔφη:<br>ἐσμυρισμέναι κόμας<br>καὶ στῆθος, ὡς ἂν καὶ γέρων ἠράσσατο<br><em>Ath. 15. 688c<\/em>"}, {"st": "—", "sp": "N", "t": "“ὁ δὲ Περικλῆς καταστρεψάμενος τὴν Σάμον ὡς ἐπανῆλθεν εῖς τὰς Ἀθήνας, ταφάς τε τῶν ἀποθανόντων κατὰ τὸν πόλεμον ἐνδόξους ἐποίησε καὶ τὸν λόγον εἰπών, ὥσπερ ἔθος ἐστίν, ἐπὶ τῶν σημάτων ἐθαυμάσθη καταβαίνοντα δ᾽ αὐτὸν ἀπὸ τοῦ βήματος αἱ μὲν ἄλλαι γυναῖκες ἐδεξιοῦντο καὶ στεφάνοις ἀνέδουν καὶ ταινίαις ὥσπερ ἀθλητὴν νικηφόρον, ἡ δ᾽ Ἐλπινίκη προσελθοῦσα πλησίον ‘ταῦτ᾽ ἔφη θ̔αυμαστά, Περίκλεις, καὶ ἄξια στεφάνων, ὃς ἡμῖν πολλοὺς καὶ ἀγαθοὺς ἀπωλέσας πολίτας οὐ Φοίνιξι πολεμῶν οὐδὲ Μήδοις ὥσπερ οὑμὸς ἀδελφὸς Κίμων, ἀλλὰ σύμμαχον καὶ συγγενῆ πόλιν καταστρεφόμενος.’ ταῦτα τῆς Ἐλπινίκης λεγούσης, ὁ Περικλῆς μειδιάσας ἀτρέμα λέγεται τὸ τοῦ Ἀρχιλόχου πρὸς αὐτὴν εἰπεῖν:<br>οὐκ ἂν μύροισι γρηῦς ἐοῦς ἠλείφεο.<br><em>Plut. Vit. Pericl. 28<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸν δὲ κρίθινον οἶνον καὶ βρῦτόν τινες καλοῦσιν ... Ἀρχίλοχος:<br>ὥσπερ παρ᾽ αὐλῷ βρῦτον ἢ Θρῆϊξ ἀνὴρ<br>ἢ Φρὺξ ἔβρυζε, κύβδα δ᾽ ἦν πονευμένη.<br><em>Ath. 10.447b<\/em>"}, {"st": "—", "sp": "N", "t": "“βάβαξ ὁ λάλος: Ἀρχίλοχος:<br>κατ᾽ οἶκον ἐστρωφᾶτο μισητὸς βάβαξ<br><em>Orion 37.4<\/em>"}, {"st": "—", "sp": "N", "t": "“παλίνσκιον: ... Ἀρχίλοχος Τριμέτροις:<br>πρὸς τοῖχον ἐκλίνθησαν ἐν παλινσκίῳ.<br>τοῦ ἐν σκοτεινῷ.”<br><em>Harp. 143.7<\/em>"}, {"st": "—", "sp": "N", "t": "“κύψαι: ἀντὶ τοῦ ἀπάγξασθαι: Ἀρχίλοχος<br>κύψαντες ὕβριν ἀθρόην ἀπέφλυσαν.<br><em>Phot. Lex. 193.22<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀρχιλόχου τε ὁμοίως εἰρηκότος:<br>ἀλλ᾽ ἄλλος ἄλλῳ καρδίην ἰαίνεται:"}, {"st": "—", "sp": "N", "t": "παρὰ τὸ Ὁμηρικόν(<em>Od. 14. 228<\/em>)<em>.<\/em>”<br><em>Clem. Al. Str. 6. 739<\/em>"}, {"st": "—", "sp": "N", "t": "“ἐγκυτί: ἐπίρρημα σημαῖνον τὸ ἐν χρῷ: Ἀρχίλοχος:<br>χαίτην ἀπ᾽ ὤμων ἐγκυτὶ κεκαρμένος"}, {"st": "—", "sp": "N", "t": "τουτέστι πρὸς αὐτῷ τῷ δέρματι.”<br><em>Et. Mag. 311. 40<\/em>"}, {"st": "—", "sp": "N", "t": "“αἰηνές: τὸ δεινὸν καὶ πολύστονον: Ἀρχίλοχος:<br>προὔθηκε παισὶ δεῖπνον αἰηνὲς φέρων.<br><em>Et. Mag. 32. 26<\/em>"}, {"st": "—", "sp": "N", "t": "“κορωνός: ὁ γαῦρος καὶ ὑψαυχενῶν ... Ἀρχίλοχος:<br>βοῦς ἐστὶν ἡμῖν ἐργάτης ἐν οἰκίῃ<br>κορωνός, ἔργων ἴδρις οὐδ᾽ ἀροῦν θέλων.<br><em>Et. Mag. 530. 27<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ περιθεῖν τοῦτο δηλοῖ (περιέχειν πανταχόθεν): οἷον καὶ Ἀρχίλοχος δηλοῖ ποιήσας:<br>τοῖον γὰρ αὐλὴν ἕρκος ἀμφιδέδρομεν.<br><em>Sch. Il. 9. 476<\/em>"}, {"st": "—", "sp": "N", "t": "“π. τῶν εἰς ι ληγόντων ἐπιρρημάτων: τὸ γοῦν Ἀρχιλόχειον συνεστάλη:<br>ἀμισθὶ γάρ σε πάμπαν οὐ διάξομεν.<br><em>Apoll. Dysc. Adv. Gram. Gr. 2. 1. 1. 161<\/em>"}, {"st": "—", "sp": "N", "t": "“ἱππομανές: ... λέγει γὰρ καὶ Ἀρχίλοχος τὸ φῦμα φυτόν:<br>ἐσθλὴν γὰρ ἄλλην οἶδα τοιούτου φυτοῦ<br>ἴησιν.<br><em>Sch. Theocr. 2. 48<\/em>"}, {"st": "—", "sp": "N", "t": "“ὁ δὲ Ὅμηρος πῶς; ἓν γὰρ ἀπὸ πολλῶν λεγέσθω: ‘ ... τρομέουσι δέ τε φρένα ναῦται ι δειδιότες: τυτθὸν γὰρ ὑπὲκ θανάτοιο φέρονται, ... ὁ δὲ ποιητὴς οὐκ εἰς ἃπαξ παρορίζει τὸ δεινόν, ἀλλὰ τοὺς ἀεὶ καὶ μόνον οὐχὶ κατὰ πᾶν κῦμα πολλάκις ἀπολλυμένους εἰκονογραφεῖ. καὶ μὴν τὰς προθέσεις ἀσυνθέτους οὔσας συναναγκάσας παρὰ φύσιν καὶ εἰς ἀλλήλας συμβιασάμενος `ὑπὲκ θανάτοιο,’ τῷ μὲν συνεμπίπτοντι πάθει τὸ ἔπος ὁμοίως ἐβασάνισε, τῇ δὲ τοῦ ἔπους συνθλίψει τὸ πάθος ἄκρως ἀπεπλάσατο, καὶ μόνον οὐκ ἐνετύπωσε τῇ λέξει τοῦ κινδύνου τὸ ἰδίωμα. οὐκ ἄλλως ὁ Ἀρχίλοχος ἐπὶ τοῦ ναυαγίου.<br>ἔστη κατ᾽ ἠκὴν κύματός τε κἀνέμου.<br><em>Longin. Subl. 10. 5<\/em> “ἥκη: ἡ ὀξύτης τοῦ σιδήρου: Ἀρχίλοχος:” <em>Et. Mag. 424. 18<\/em>"}, {"st": "—", "sp": "N", "t": "“συμβόλους δὲ λέγομεν πταρμοὺς ἢ φήμας ἢ ἀπαντήσεις: ὡς Ἀρχίλοχος:<br>μετέρχομαί σε σύμβολον ποιεύμενος.<br><em>Sch. Pind. Ol. 12.10<\/em>"}, {"st": "—", "sp": "N", "t": "“ἐπειδὴ γὰρ ἐκεῖνοι σοφὸν ὠνόμαζον τὸν ἡντινοῦν ἐπιόντα τέχνην, ὧν εἷς ἦν καὶ Ἀρχίλοχος λέγων:<br>τρίαιναν ἐσθλὸς καὶ κυβερνήτης σοφός<br><em>Ammon. in Porph. Isag. Proem. 9. 8<\/em>"}, {"st": "—", "sp": "N", "t": "“φηλήτου δὲ τοῦ εἰρημένου χρῆσις μὲν παρά τε Ἡσιόδῳ καὶ παρὰ Ἀρχιλόχῳ ἐν τῷ:<br>φηλῆτα νύκτωρ περὶ πόλιν πωλεύμενε"}, {"st": "—", "sp": "N", "t": "ἤγουν κλέπτῃ νυκτιλόχῳ.”<br><em>Eust. Od. 1889. 1<\/em>"}, {"st": "—", "sp": "N", "t": "“π. κλίς. ὀνομ. 2. 679. 5 μύκης: ... σημαίνει δὲ καὶ τὸ αἴδοιον του ανθρώπου, ὅπερ ἰσοσύλλαβως ἔκλινεν Ἀρχίλοχος:<br>ἀλλ᾽ ἀπερρώγασί μοι<br>μύκ εω τένοντες.<br><em>Hdn.<\/em>"}, {"st": "—", "sp": "N", "t": "“κλίνεται δὲ καὶ ὡς σπονδειακόν, Ἄρης, Ἄρου, ὅθεν κατ᾽ Ἰάδα διάλεκτον ἐπεκτείνας Ἀρχίλοχος ἔφη ἐν τοῖς Τριμέτροις:<br>παῖδ᾽ Ἄρ εω μιηφόνου<br><em>Eust. ll. 518.28<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... πρεσβευτικῇς ... ἡλικίας, ᾗτινι συμφέρειν τὴν ἀπραγμοσύνην Ἀρχίλοχος ὁ ποιητὴς ἀπεφήνατο.<br>βίος δ᾽ ἀπράγμων τοῖς γέρουσι συμφέρει<br>μάλιστα δ᾽ ει᾽ τύχοιεν ἁπλόοι τρόποις<br>ἢ μακκοᾶν μέλλοιεν ἢ ληρεῖν ὅλως,<br>ὅπερ γερόντων ἐστίν.<br><em>Cedren Hist. Comp. 2. 612. 9 :<\/em> “μακκοᾶν: διαλέγεσθαι ... οἷον:” <em>Et. Magn. Vet.<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>Σαπαίων"}, {"st": "—", "sp": "N", "t": "δὲ τούτων καὶ Ἀρχίλοχος ἐν ἰαμβείῳ μνήμην ἔσχε.”<br><em>Paus. 7. 10. 6<\/em>"}, {"st": "—", "sp": "HDR", "t": "Iambi Tetrameters"}, {"st": "—", "sp": "N", "t": "“ὦ σοφώτατοι γεωργοί, τἀμὰ δὴ ξυνίετε ι ῥήματα: πρὸς ταῦτα καὶ Κρατῖνος ἐν Πυτίνῃ πεποίηκεν: ‘ὦ λιπερνῆτες πολῖται, τἀμὰ δὴ ξυνίετε:’5 ἔστι δέ πρὸς τὰ Ἀρχιλόχου:<br>ὦ λιπερνῆτες πολῖται, τἀμὰ δὴ ξυνίετε<br>ῥήματ᾽.<br><em>Sch. Ar. Pac. 603<\/em>"}, {"st": "—", "sp": "N", "t": "“τῶν δ᾽ ἐν Πάρῳ τῇ νήσῳ (σύκων) ... Ἀρχίλοχος μνημονεύει, λέγων οὕτως:<br>ἔα Πάρον καὶ σῦκα κεῖνα καὶ θαλάσσιον βίον.<br><em>Ath. 3. 76b<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἡσίοδον μέντοι καὶ Ἀρχίλοχον ἤδη εἰδέναι (φησὶν Ἀπολλόδωρος) καὶ Ἕλληνας λεγομένους τοὺς σύμπαντας καὶ Πανέλληνας: τὸν μὲν περὶ τῶν Προιτίδων λέγοντα, ὡς Πανέλληνες ἐμνήστευον αὐτάς, τὸν δέ:<br>ὡς Πανελλήνων ὀϊζὺς ἐς Θάσον συνέδραμεν.<br><em>Str. 8. 370<\/em>"}, {"st": "—", "sp": "N", "t": "“Ἀλκαῖος καὶ Ἀλκμὰν λίθον φασὶν ἐπαιωρεῖσθαι τῷ Ταντάλῳ: ... ἐποίησε δὲ καὶ Ἀρχίλοχος:<br>μηδ᾽ ὁ Ταντάλου λίθος<br>τῆσδ᾽ ὑπὲρ νήσου κρεμάσθω.<br><em>Sch. Pind. Ol. i. 97 ...<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... καθάπερ Ἀρχίλοχος μὲν τοῖς Θρακικοῖς ἀπειλημμένος δεινοῖς τὸν πόλεμον εἰκάζει θαλαττίῳ κλύδωνι, λέγων ὧδέ πως:<br>Γλαῦχ᾽, ὅρα: βαθὺς γὰρ ἤδη κύμασιν ταράσσεται<br>πόντος, ἀμφὶ δ᾽ ἄκρα Γυρέων ὀρθὸν ἵσταται νέφος,<br>σῆμα χειμῶνος: κιχάνει δ᾽ ἐξ ἀελπτίης φόβος.<br><em>Heracl. All. Hom. 5<\/em>"}, {"st": "—", "sp": "N", "t": "“π. Ἀρχιλόχου: ἔτι κἀκεῖνο μεταφράζων ‘νίκης ἀνθρώποισι θεῶν ἐκ πείρατα κεῖται’ διὰ τοῦδε τοῦ ἰάμβου δῆλός ἐστι:<br>καὶ νέους θάρσυνε: νίκης δ᾽ ἐν θεοῖσι πείρατα.<br><em>Clem. Al. Str. 6. 739<\/em>"}, {"st": "—", "sp": "N", "t": "“ὅτι ἀβέβαιος ἡ τῶν ἀνθρώπων εὐπραξία μεταπιπτούσης ῥᾳδίως τῆς τύχης: Ἀρχιλόχου:<br>τοῖς θεοῖς τιθεῖο πάντα: πολλάκις μὲν ἐκ κακῶν<br>ἄνδρας ὀρθοῦσιν μελαίνῃ κειμένους ἐπὶ χθονί,<br>πολλάκις δ᾽ ἀνατρέπουσι καὶ μάλ᾽ εὖ βεβηκότας<br>ὑπτίους κλίνουσ᾽: ἔπειτα πολλὰ γίγνεται κακά,<br>καὶ βίου χρήμῃ πλανᾶται καὶ νόου παρήορος.<br><em>Stob. Fl. 105. 24<\/em>"}, {"st": "—", "sp": "N", "t": "“οἱ νεώτεροι κέρας τὴν συμπλοκὴν τῶν τριχῶν ὁμοίαν κέρατι:<br>τὸν κεροπλάστην ἄειδε Γλαῦκον ...<br><em>Sch. Il. 24. 81<\/em> “κέρας γὰρ τὴν τρίχα λέγεσθαι. καὶ τὸ κείρασθαι διὰ τοῦτο καὶ τὴν κουράν: καὶ τὸν παρ᾽ Ἀρχιλόχῳ κεροπλάστην φιλόκοσμον εἶναι περὶ κόμην καὶ καλλωπιστήν.” <em>Plut. Soll. An. 24<\/em>"}, {"st": "—", "sp": "N", "t": "“ὁ δὲ Ἀρχίλοχος ... περὶ στρατηγοῦ λέγων οὕτω φησίν:<br>οὐ φιλέω μέγαν στρατηγὸν οὐδὲ διαπεπλιγμένον<br>οὐδὲ βοστρύχοισι γαῦρον οὐδ᾽ ὑπεξυρημένον,<br>ἀλλά μοι σμικρός τις εἴη καὶ περὶ κνήμας ἰδεῖν<br>ῥοικός, ἀσφαλ εώ ς βεβηκὼς ποσσι, καρδίης πλέως.<br><em>Dio Chrys. 2. 456<\/em>"}, {"st": "—", "sp": "N", "t": "“ἀλλὰ γὰρ καὶ τούτου τὴν κεφαλὴν ἀποτεμόντες καὶ Λάκωνος ἐκόμισαν πρὸς τὸν Ὄθωνα δωρεὰς αἰτοῦντες. ὡς δέ φησιν Ἀρχίλοχος:<br>ἑπτὰ γὰρ νεκρῶν πεσόντων, οὓς ἐμάρψαμεν ποσίν,<br>χίλιοι φονῆες ἐσμέν:"}, {"st": "—", "sp": "N", "t": "οὕτως τότε πολλοὶ τοῦ φόνου μὴ συνεφαψάμενοι, χεῖρας δὲ καὶ ξίφη καθαιμάσσοντες ἐπεδείκνυντο καὶ δωρεὰς ᾔτουν βιβλία διδόντες τῷ Ὄθωνι.”<br><em>Plut. Vit. Galb. 27<\/em>"}, {"st": "—", "sp": "N", "t": "“ὁ δὲ τροχαῖος (ἐκλήθη) ὅτι τροχαλὸν ἔχει τὸν ῥυθμόν: καὶ γὰρ Ἀρχίλοχος ἐπὶ τῶν θερμῶν ὑποθέσεων αὐτῷ κέχρηται, ὡς ἐν τῷ:<br>Ἐρξίη, πῇ δηὖτ᾽ ἄνολβος ἀθροΐζεται στρατός;<br><em>Anecd. Var. Schoell i. 206. 3<\/em>"}, {"st": "—", "sp": "N", "t": "“π. σῆψιν κρέων: ... τὸν δὲ ἥλιον ἀναρπάζειν μᾶλλον ἐκ τῶν σωμάτων τὸ νοτερὸν διὰ τὴν πύρωσιν: πρὸς ὃ καὶ τὸν Ἀρχίλοχον εἰρηκέναι φυσικῶς:<br>ἔλπομαι, πολλοὺς μὲν αὐτῶν Σείριος καταυανεῖ<br>ὀξὺς ἐλλάμπων.<br><em>Plut. Quaest. Conv. 3. 10. 2<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... καθάπερ ἀμέλει κἀκεῖνο τὸ ἔπος(<em>Il. 18. 309<\/em>)’ξυνὸς Ἐννάλιος καί τε κτανέοντα κατέκτα,’ μεταποιῶν αὐτὸς (ὁ Ἀρχίλοχος) ὧδέ πως ἐξήνεγκεν:<br>ἐρξάτω δ᾽: ἐτήτυμον γὰρ ξυνὸς ἀνθρώποις Ἄρης.<br><em>Clem. Al. Str. 6. 739<\/em>"}, {"st": "—", "sp": "N", "t": "“ὅτι τῶν πλείστων μετὰ θάνατον ἡ μνήμη διαρρεῖ ταχέως: Ἀρχιλόχου:<br>οὔ τις αἰδοῖος μετ᾽ ἀστῶν οὐδὲ περίφημος θανὼν<br>γίγνεται: χάριν δὲ μᾶλλον τοῦ ζοοῦ διώκομεν<br>ζῶντες ἔτι: κάκιστα δ᾽ αἰεὶ7 τῷ θανόντι γίγνεται.<br><em>Stob. Fl. 126. 4<\/em>"}, {"st": "—", "sp": "N", "t": "“ὅτι οὐ χρὴ παροινεῖν εἰς τοὺς τετελευτηκότας: Ἀρχιλόχου:<br>οὐ γὰρ ἐσθλὰ κατθανοῦσι κερτομεῖν ἐπ᾽ ἀνδράσιν.<br><em>Stob. Fl. 125. 5<\/em>"}, {"st": "—", "sp": "N", "t": "“ὅτι οἱ τὰ ἄδικα πράσσοντες μέλλουσιν κολάζεσθαι: ὁμοίως καὶ Ἀρχίλοχος:<br>ἓν δ᾽ ἐπίσταμαι μέγα,<br>τὸν κακῶς με δρῶντα δέννοις8 ἀνταμείβεσθαι κακοῖς.<br><em>Theophil. Autol. 2. 37. 377<\/em>"}, {"st": "—", "sp": "N", "t": "“π. ὀργῆς:<br>θυμέ, θύμ᾽ ἀμηχάνοισι κήδεσιν κυκώμενε,<br>ἀνάδυ, δυσμενῶν δ᾽ ἀλέξευ προσβαλὼν ἐναντίον<br>στέρνον ἐνδόκοισιν, ἐχθρῶν πλησίον κατασταθεὶς<br>ἀσφαλέως: καὶ μήτε νικῶν ἀμφαδην̀ ἀγάλλεο<br>μήτε νικηθεὶς ἐν οἴκῳ καταπεσὼν ὀδύρεο:<br>ἀλλὰ χαρτοῖσίν τε χαῖρε καὶ κακαῖσιν ἀσχάλα<br>μὴ λίην: γίγνωσκε δ᾽ οἷος ῥυσμὸς ἀνθρώπους ἔχει.<br><em>Stob. Fl. 20. 28<\/em>"}, {"st": "—", "sp": "N", "t": "“πρὸς γὰρ τοὺς συνήθεις καὶ φίλους ὁ θυμὸς αἴρεται μᾶλλον ἢ πρὸς τοὺς ἀγνῶτας ὀλιγωρεῖσθαι νομίσας: διὸ καὶ Ἀρχίλοχος προσηκόντως τοῖς φίλοις ἐγκαλῶν διαλέγεται πρὸς τὸν θυμόν:<br>σὺ γὰρ δὴ παρὰ φίλων ἀπάγχεαι.<br><em>Arist. Pol. 7. 1328 a. 1<\/em>"}, {"st": "—", "sp": "N", "t": "“π. δίψης μεταφορικῶς: τῆς δὲ δίψης οὐδέν ἐστι πολυποθητότερον. διόπερ καὶ τὸ Ἄργος πολυδίψιον ὁ ποιητὴς ἔφη, τὸ πολυπόθητον διὰ τὸν χρόνον ... διὸ καὶ ὁ Σοφοκλῆς φησι ... καὶ ὁ Ἀρχίλοχος:<br>μάχης δὲ τῆς σῆς, ὥστε διψέων πιεῖν,<br>ὣς ἐρέω .<br><em>Ath. 10. 433e<\/em>"}, {"st": "—", "sp": "N", "t": "“π. τοῦ πολυπτώτου: ἔστι δὲ τὸ τοιοῦτον σχῆμα καὶ παρά τισι τῶν ποιητῶν, ὡς παρὰ Ἀρχιλόχῳ:<br>νῦν δὲ Λ εώ φιλος μὲν ἄρχει, Λ εώ φιλος δ᾽ ἐπικρατεῖ,<br>λ εω φίλῳ δὲ πάντα κεῖται, Λ εώ φιλος δ᾽ ἀκουέτω.<br><em>Hdn. π. σχημ. 57. 2<\/em>"}, {"st": "—", "sp": "N", "t": "“Ὅμηρον μεταφράζων, ὅτε φησί: ‘τοῖος γὰρ νόος ἐστὶν ἐπιχθονίων ἀνθρώπων, ι οἷον ἐπ᾽ ἦμαρ ἄγῃσι πατὴρ ἀνδρῶν τε θεῶν τε’(<em>Od. 18. 135<\/em>), ὁ Ἀρχίλοχος:<br>τοῖος ἀνθρώποισι θυμός, Γλαῦκε, Λεπτίν εω πάϊ,<br>γίγνεται θνητοῖς, ὁκοῖον Ζεὺς ἐφ᾽ ἡμέρην ἄγῃ,<br>καὶ φρονεῦσι τοῖ᾽ ὁκοίοις ἐγκυρέωσιν ἔργμασιν.<br><em>Theon Prog. i. 153 W<\/em>"}, {"st": "—", "sp": "N", "t": "“‘εἱ γὰρ ὤφελον’ φησὶν ἕκαστος τῶν εὐχομένων, καὶ Ἀρχίλοχος:<br>ει᾽ γὰρ ὣς ἐμοὶ γένοιτο χεῖρα Νεοβούλης θιγεῖν.<br><em>Plut. de E 5<\/em>"}, {"st": "—", "sp": "N", "t": "“ἀσκὸν τοίνυν λέγει τὸν περὶ τὴν γαστέρα τόπον: Ἀρχίλοχος:<br>καὶ πεσεῖν δρήστην ἐπ᾽ ἀσκὸν κἀπὶ γαστρὶ γαστέρα<br>προσβαλεῖν μηρούς τε μηροῖς.<br><em>Sch. Eur. Med. 679<\/em>"}, {"st": "—", "sp": "N", "t": "“αὖθίς τε ὁ Ἀρχίλοχος τὸ Ὁμηρικὸν ἐκεῖνο μεταφέρων(<em>Il. 9. 116<\/em>): ‘ἀασάμην οὐδ᾽ αὐτὸς ἀναίνομαι, ἀντί νυ πολλῶν’ ὧδέ πως γράφει:<br>ἤμβλακον, καί πού τιν᾽ ἄλλον ἥδ᾽ ἄτη κιχήσατο.<br><em>Clem. Al. Str. 6. 739<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... καὶ ὡς Ἀρχίλοχος ψέγει: ποιεῖ γὰρ τὸν πατέρα λέγοντα περὶ τῆς θυγατρὸς ἐν τῷ ἰάμβῳ:<br>χρημάτων ἄελπτον οὐδέν ἐστιν οὐδ᾽ ἀπώμοτον<br>οὐδὲ θαυμάσιον, ἐπειδὴ Ζεὺς πατὴρ Ὀλυμπίων<br>ἐκ μεσημβρίης ἔθηκε νύκτ᾽ ἀποκρύψας φάος<br>ἡλίῳ λάμποντι: λυγρὸν δ᾽ ἦλθ᾽ ἐπ᾽ ἀνθρωπους δέος.<br>ἐκ δὲ τοῦ καὶ πιστὰ πάντα κἀπίελπτα γίγνεται<br>ἀνδράσιν: μηδεὶς ἔθ᾽ ὑμῶν εἰσορῶν θαυμαζέτω,<br>μηδ᾽ ὅταν δελφῖσι θῆρες ἀνταμείψωνται νομὸν<br>ἐνάλιον καὶ σφιν θαλάσσης ἠχέεντα κύματα<br>φίλτερ᾽ ἠπείρου γένηται τοῖσί τ᾽ ἡδὺ ἦν ὄρος.<br><em>Arist. Rhet. 3. 1418 b. 28<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... οἷον εὐθὺς ὁ Ἀρχίλοχος ὅταν μὲν εὐχόμενος λέγῃ:<br>κλῦθ᾽ ἄναξ Ἥφαιστε καὶ μοι σύμμαχος γουνουμένῳ<br>ἵλαος γενεῦ, χαρίζευ δ᾽ οἷά περ χαρίζεαι.<br><em>Plut. Aud. Poet. 6<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ γὰρ ἐξάρχειν τῆς φόρμιγγος ἴδιον: διόπερ ὁ μὲν Ἠσίοδός φησιν ... καὶ ὁ Ἀρχίλοχος:<br>αὐτὸς ἐξάρχων πρὸς αὐλὸν Λέσβιον παιήονα<br><em>Ath. 4. <\/em>(<em>5<\/em>)<em> 180 e, p. 414 Kaib.<\/em>"}, {"st": "—", "sp": "N", "t": "“Φιλόχορος δέ φησιν ὡς οἱ παλαιοὶ σπένδοντες οὐκ ἀεὶ διθυραμβοῦσιν, ἀλλ᾽ ὅταν σπένδωσι, τὸν μὲν Διόνυσον ἐν οἴνῳ καὶ μέθῃ τὸν δὲ Ἀπόλλωνα μεθ᾽ ἡσυχίας καὶ τάξεως μέλποντες. Ἀρχίλοχος γοῦν φησιν:<br>ὡς Διωνύσοι᾽ ἄνακτος καλὸν ἐξάρξαι μέλος<br>οἶδα διθύραμβον οἴνῳ συγκεραυνωθεὶς φρένας.<br><em>Ath. 14. 628 a<\/em>"}, {"st": "—", "sp": "N", "t": "“περὶ Περικλέους φησὶν Ἀρχίλοχος ... ὡς ἀκλήτου ἐπεισπαίοντος εἰς τὰ συμπόσια Μυκονίων δίκην: ...<br>πολλὸν δὲ πίνων καὶ χαλίκρητον μέθυ,<br>οὔτε τῖμον εἰσενέγκας<br>... οὐδὲ μὴν κληθεὶς ἐς ῆλθες οἷα δὴ ᾿ς φίλους φίλος<br>ἀλλά σ᾽ εὖ γαστὴρ νόον τε καὶ φρένας παρήγαγεν<br>εἰς ἀναιδείην.<br><em>Ath. i. 7 f<\/em>"}, {"st": "—", "sp": "HDR", "t": "Iambi Asynartete Tetrameters"}, {"st": "—", "sp": "N", "t": "“π. ἀσυναρτήτων: πρῶτος δὲ καὶ τούτοις Ἀρχίλοχος κέχρηται: πῇ μὲν γὰρ ἐποίησεν ἔκ τε ἀναπαιστικοῦ ἑφθημιμεροῦς καὶ τροχαϊκοῦ ἡμιολίου τοῦ καλουμένου ἰθυφαλλικοῦ: ‘Ἐρασμονίδη’ κτλ. τοῦτο δὲ οἱ μετ᾽ αὐτὸν οὐχ ὁμοίως αὐτῷ ἔγραψαν. οὗτος μὲν γὰρ τῇ τε τομῇ δι᾽ ὅλου κέχρηται καὶ σπονδείους παρέλαβεν ἐν τῷ ἀναπαιστικῷ κώλῳ οἷον ‘ἀστῶν δὲ’ κτλ., οἱ δὲ μετ᾽ αὐτὸν τῇ μὲν τομῇ ἀδιαφόρως ἐχρήσαντο, ὥσπερ Κρατῖνος ...<br>ἐρασμονίδη Χαρίλαε, χρῆμά τοι γελοῖον<br>ἐρέω , πολὺ φίλταθ᾽ ἑταίρων, τέρψεαι δ᾽ ἀκούων.<br>φιλέε ιν στυγνόν περ ἐόντα μηδὲ διαλέγεσθαι<br>ἀστῶν δ᾽ οἱ μὲν κατόπισθεν ᾖσαν, οἱ δὲ πολλοὶ<br>Δήμητρί τε χεῖρας ἀνέξων<br><em>Heph. 15. 2. p. 47 Cons.<\/em> “ὑπονοήσειε δ᾽ ἄν τις καὶ τρίτην διαφορὰν εἶναι τῷ Ἀρχιλόχῳ πρὸς τοὺς μετ᾽ αὐτόν, καθ᾽ ἣν ἀναπαίστῳ δοκεῖ τῷ πρώηῳ χρῆσθαι, ‘ἐρέω’ κτλ., ‘φιλέειν’ κτλ., ᾧ οὐκ ἐχρήσαντο ἐκεῖνοι. φαίνεται δὲ οὐδ᾽ αὐτὸς κεχρημένος: δύναται γὰρ ἀμφότερα κατὰ συνεκφώνησιν εἰς ἴαμβον περιϊστασθαι.” <em>Heph. 15. 6. p. 49<\/em> “π. ἀναπαιστικοῦ: πρῶτος δὲ Ἀρχίλοχος ἐχρήσατο τῷ μεγέθει τούτῳ, ἐν τοῖς Τετραμέτροις προτάξας αὐτὸ τοῦ ἰθυφαλλικοῦ: τὸ γὰρ ‘Ἐρασμονίδη Χαρίλαε’ ἑφθημιμερές ἐστιν ἀναπαιστικόν: ἐχρήσατο δὲ τῷ πρώτῳ ποδὶ καὶ ἰάμβῳ, ὡς καὶ ἐκ τοῦ παραδείγματός ἐστι δῆλον, καὶ σπονδείῳ Δ̔ήμητρι᾽ κτλ. ἀναπαίστῳ δὲ τῷ πρώτῳ ἐπὶ δύο μόνων στίχων κεχρῆσθαι δοκεῖ ‘ἐρέω’ κτλ. καὶ ‘φιλέειν’ κτλ. ταῦτα δὲ ἀμφότερα κατὰ συνεκφώνησιν ἴαμβον ἔχει τὸν πρῶτον πόδα.” <em>Heph. 8. 7. p. 27<\/em>"}, {"st": "—", "sp": "N", "t": "“περὶ δὲ Θυὸς τοῦ Παφλαγόνων βασιλέως ὅτι καὶ αὐτὸς ἦν πολυφάγος προειρήκαμεν (4. 144 φ) ... Ἀρχίλοχος δ᾽ ἐν Τετραμέτροις Χαρίλαν εἰς τὰ ὅμοια διαβέβληκεν.” <em>Ath. 10. 415 d<\/em>"}, {"st": "—", "sp": "N", "t": "“ ... τὰ παρὰ τῇ γραφῇ διαφορούμενα: εἰσὶ ταῦτα ... εἴκελος ἀστεροπῇ καὶ τὸ ἴκελος ... βακχεία καὶ<br>ἕωθεν ἕκαστος ἔπινεν: ἐν δὲ βακχίῃσιν<br>Ἀρχίλοχος.”<br><em>Gram. ap. Welcker Opusc. 4. 50<\/em>"}, {"st": "—", "sp": "HDR", "t": "Epodes"}, {"st": "—", "sp": "N", "t": "“ψόγος Ἀφροδίτης: καὶ ὅτι φαῦλον ὁ ἔρως καὶ πόσων εἴη κακῶν γεγονὼς αἴτιος: Ἀρχιλόχου:<br>δύστηνος ἔγκειμαι πόθῳ<br>ἄψυχος, χαλεπῇσι θεῶν ὀδύνῃσιν ἕκητι<br>πεπαρμένος δι᾽ ὀστέων.<br><em>Stob. Fl. 64. 12.<\/em>"}, {"st": "—", "sp": "N", "t": "“τρίτον δέ ἐστι παρὰ Ἀρχιλόχῳ ἀσυνάρτητον ἐκ δακτυλικοῦ πενθημιμεροῦς καὶ ἰαμβικοῦ διμέτρου ἀκαταλήκτου:<br>ἀλλά μ᾽ ὁ λυσιμελής, ὦ τ᾽αῖρε, δάμναται πόθος.<br><em>Heph. 15. 9. p. 50 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“αἶνος καὶ παροιμία: ὁ μὲν γὰρ αἶνός ἐστι λόγος κατὰ ἀναπόλησιν μυθικὴν ἀπὸ ἀλόγων ζῴων ἢ φυτῶν πρὸς ἀνθρώπους εἰρημένος, ὥς φησι Λούκιος Ταρραῖος ἐν πρώτῳ Παροιμιῶν, οἷον ἀπὸ μὲν ἀλόγων ζαῴων ὡς παρ᾽ Ἀρχιλόχῳ:<br>αἶνός τις ἀνθρώπων ὅδε<br>ὡς ἆρ᾽ ἀλώπηξ καἰετὸς ξυνωνίην<br>ἔμειξαν.<br><em>Ammon. 6. Valck. Words Alike but Different:<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>‘ὁρᾷς ἵν᾽ ἔστ᾽ ἐκεῖνος ὑψηλὸς πάγος<br>τρηχύς τε καὶ παλίγκοτος;<br>ἐν τῷ κάθημαι σὴν ἐλαφρίζων μάχην:’"}, {"st": "—", "sp": "N", "t": "ἐπὶ τοῦτον τὸν ὑψηλὸν πάγον τὸ δριμὺ καὶ πανοῦργον ἐκεῖνο θηρίον ἀνελθεῖν ἀδύνατον: ἵνα δὲ εἰς ταὐτὸν ἔλθῃ τοῖς ἀετοῦ γεννήμασιν ἀλώπηξ, ἢ τύχῃ τινὶ δεῖ χρησαμένους ἐκείνους πονηρᾷ καταπεσεῖν εἰς γῆν τῶν οἴκων αὐτοῖς φθαρέντων, ἢ φύσασαν αὐτὴν ἃ μὴ πέφυκε φύειν, λαιψηρὰ κυκλῶσαι πτερά, καὶ οὕτως ἀρθεῖσαν ἐκ γῆς ἀναπτέσθαι πρὸς τὸν ὑψῃλὸν πάγον. ἕως δὲ ἑκάτερον ἐπὶ τῆς οἰκείας μένει τάξεως, οὐκ ἔνι κοινωνία τοῖς γῆς πρὸς τὰ οὐρανοῦ θρέμματα:<br>ε.γ. ‘ ... ἢ τύχῃ τινὶ<br>κείνους πονηρᾷ καταπεσεῖν ἐς γῆν δέει<br>οἴκου φθαρέντος, ἢ σέ γε<br>φύειν ἃ μὴ πέφυκε φύσασαν, τόθεν<br>λαιψηρὰ κυκλῶσαι πτερά.<br>ἕως δὲ νῷν ἑκάτερος ἔνθ᾽ ἔστιν μένῃ,<br>τέως οὐκ ἔνι ξυνωνίη<br>τοῖς θρέμμασιν γῆς πρὸς τὰ θρέμματ᾽ οὐρανοῦ.’<br><em>Atticus ap. Euseb. Praep. Ev. 15. 795 a<\/em>"}, {"st": "—", "sp": "N", "t": "“π. δίκης παρὰ τοῦ θεοῦ τεταγμένης ἐποπτεύειν τὰ ἐπὶ γῆς γιγνόμενα ὑπὸ τῶν ἀνθρώπων, τιμωρον οὖσαν τῶν ἁμαρτανόντων: Ἀρχιλόχου:<br>ὦ Ζεῦ, πάτερ Ζεῦ, σὸν μὲν οὐρανοῦ κράτος,<br>σὺ δ᾽ ἔργ᾽ ἐπ᾽ ἀνθρώπων ὁρᾷς<br>λεωργὰ καὶ θεμιστά, σοὶ δὲ θηρίων<br>ὕβρις τε καὶ δίκη μέλει.<br><em>Stob. Ecl. Phys. i. 3. 34<\/em>"}, {"st": "—", "sp": "N", "t": "“π. Ἀρχιλόχου: ... καὶ πάλιν ὅταν λέγῃ:<br>ἐρέω τιν᾽ ὑμῖν αἶνον, ὦ Κηρυκίδη,<br>ἀχνυμένη σκυτάλη:<br>πίθηκος ᾔει θηρίων ἀποκριθεὶς<br>μοῦνος ἀν᾽ ἐσχατίην:<br>τῷ δ᾽ ἆρ᾽ ἀλώπηξ κερδαλέη συνήντετο<br>πυκνὸν ἔχουσα νόον.<br><em>Ammon. 6 Valck.<\/em>"}, {"st": "—", "sp": "N", "t": "“σκανδάληθρον: τὸ πέταυρον τῶν παγίδων ... ἔστι δὲ τὸ ἐν τῇ παγίδι καμπύλον ξύλον ᾧ ἐρείδεται. Ἀρχίλοχος δὲ ῥόπτρον ἔφη, οἷον:<br>ῥόπτρῳ ἐρειδόμενον<br><em>Et. Magn. 715. 44<\/em>"}, {"st": "—", "sp": "N", "t": "“τοιόνδε δ᾽, ὦ πίθηκε, τὸν πώγων ἔχων ι εὐνοῦχος ἡμῖν ἦλθες ἐσκευασμένος;: καὶ τοῦτο παρῴδηκεν ἐκ τῶν Ἀρχιλόχου Ἐπῳδῶν:<br>‘τ̔οίηνδε δ᾽, ὦ πίθηκε, τὴν πυγὴν ἔχων . .;’<br><em>Sch. Ar. Ach. 120<\/em>"}, {"st": "—", "sp": "N", "t": "“καταπροΐξασθαι: ἀπὸ τοῦ προικός, ἣν διαιροῦντες οἱ Ἴωνες πρόϊκα λέγουσιν, ὥσπερ ἡ προΐξ: ου δωρεὰν δίδοται, φησίν, οὐ δ᾽ ἐν δώρου μέρει12 μου καταγνώσεταίτις, ἀλλ᾽ ἀποδώσει μισθὸν ὧν ἐπράξατο. καὶ ὁ ἐπαιτής καὶ ὁ προῖκα αἰτῶν προΐκτης λέγεται: οὕτω εὗρον ἐν Ὑπομνήματι Ἐπῳδῶν Ἀρχιλόχου.<br>ἐμεῦ δ᾽ ἐκεῖνος οὐ καταπροΐξεται.<br><em>Cram. A.P. 4. 55. 12<\/em> “προΐκτης: ... τινὲς δὲ παρὰ τὸ ἵξεσθαι, δωρεάν τινα λαμβάνειν, ὡς Ἀρχίλοχος:” <em>Et. Magn. 689. 1<\/em>"}, {"st": "—", "sp": "N", "t": "“οὐ μὴν ἀλλὰ ἡ Τύχη, καθάπερ ἡ παρ᾽ Ἀρχιλόχῳ γυνή:<br>τῇ μὲν ὕδωρ ἐφόρει<br>δολοφρονέουσα χειρί, θἠτέρῃ δὲ πῦρ:"}, {"st": "—", "sp": "N", "t": "δεινοῖς αὐτὸν οὕτω καὶ φοβεροῖς ἀγγέλμασιν ἀποστήσασα τῆς Λακεδαίμονος εὐθὺς ἑτέρας πραγμάτων καινῶν καὶ μεγάλων ἐπήνεγκεν ἐλπίδας ἐκ τοιαύτης αἰτίας.”<br><em>Plut. Vit. Demetr. 35<\/em>"}, {"st": "—", "sp": "N", "t": "“εἰσὶ δὲ ἐν τοῖς ποιήμασι καὶ οἱ ἀρρενικῶς οὕτω καλούμενοι ἐπῳδοί, ὅταν μεγάλῳ στίχῳ ἔλαττόν τι ἐπιφέρηται οἷον:<br>πάτερ Λυκάμβα, ποῖον ἐφράσω τόδε;<br>τίς σὰς παρήειρε φρένας<br>ᾗς τὸ πρὶν ἠρήρεισθα; νῦν δὲ πολὺς<br>ἀστοῖσι φαίνεαι γέλως.<br><em>Heph. π. ποιημ. ⟩7.2. p.71 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>Δωτάδης<br> <br>Δώτου υἱός, ὁ Λυκάμβας.”<br><em>Hesych.<\/em>"}, {"st": "—", "sp": "N", "t": "“π. τὸ τέο ἀντὶ τοῦ τίνος: τοῦτο τὸ τέω τετόλμηται καὶ τέου οἷον<br>τίς ἆρα δαίμων καὶ τέου χολούμενος ... ,:<br><em>Et. Magn. 752. 15n<\/em>"}, {"st": "—", "sp": "N", "t": "“τίς γὰρ οὐκ οἷδεν ὅτι πολλοὶ κοινωνήσαντες ἁλῶν καὶ τραπέξης ἐπεβούλευσαν τοῖς συνεστίοις; καὶ πλήρης ἐστὶν ἡ Ἑλλήνων καὶ βαρβάρων ἱστορία τοιούτων παραδειγμάτων. καὶ ὀνειδίζων γε ὁ Πάριος ἰαμβοποιὸς τὸν Λυκάμβην κατὰ ‘ἅλας καὶ τράπεζαν’ συνθήκας ἀθετήσαντά φησι πρὸς αὐτόν:<br>ὅρκον δ᾽ ἐνοσφίσθης μέγαν<br>ἅλας τε καὶ τράπεζαν<br><em>Orig. adv. Cels. 2.21 K<\/em> “τὸν Ἀρχίλοχον οὐδὲν ὤνησαν οἱ ἅλες καὶ ἡ τράπεζα πρὸς τὴν ὁμολογίαν τῶν γάμων, ὥς φησιν αὐτός.” <em>Dio Chrys. 74. 16<\/em>"}, {"st": "—", "sp": "N", "t": "“κήλων μὲν πεποίηται ἀπὸ τῶν ὀχευτῶν ὄνων: Ἀρχίλοχος: ‘ὥστ᾽ ὄνου’ κτλ.<br>ἡ δέ οἱ σάθη<br>ὡσεί τ᾽ ὄνου Πριηνέος<br>κήλωνος ἐπλήμμυρεν ὀτρυγηφάγου.<br><em>Eust. Od. 1597. 28<\/em> “τρύγη δέ ἐστιν ὁ Δημητριακὸς καρπός, ὥσπερ ‘ὄνου κήλωνος ὀτρυγηφάγου’ ἀντὶ τοῦ κριθοφάγου κατὰ πλεονασμὸν τοῦ ο, ὡς ἐπὶ τοῦ κρυόεις ὀκρυόεις: ὡς παρὰ Ἀρχιλόχῳ.” <em>Et. Magn. 167. 25<\/em> “Ἀρχίλοχος:” <em>Et. Sorb. ap. Gaisf. p. 166. 21 n.<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>... <br>κύματι πλαζόμενος,<br>κἀν Σαλμυδης σῷ γυμνὸν εὐφρονέων ἐτέων<br>Θρήϊκες ἀκρόκομοι<br>λάβοιεν, ἔνθα πόλλ᾽ ἀναπλήσει κακὰ<br>δούλιον ἄρτον ἔδων,<br>ῥίγει πεπηγότ᾽ αὐτον, ἐκ δὲ τοῦ ῥόθου<br>φυκία πόλλ᾽ ἐπέχοι,<br>κροτέοι δ᾽ ὀδόντας, ὡς κύων ἐπὶ στόμα<br>κείμενος ἀκρασίῃ<br>ἄκρον παρὰ ῥηγμῖνα, κῦμα δ᾽ ἐξεμέοι.<br>ταῦτ᾽ ἐθέλοιμ᾽ ἂν ἰδεῖν,<br>ὅς μ᾽ ἠδίκησε λὰξ δ᾽ ἐφ᾽ ὁρκίοις ἔβη<br>τὸ πρὶν ἑταῖρος ἐών.<br><em>Pap. Argentorat. Sitz. b. Berl. Akad. 1899. 857<\/em>"}, {"st": "—", "sp": "N", "t": "“ ἡ χλαῖνα δηλοῖ σχετλίη, σ᾽ ἐσταλμένη<br>κυρτόν, ὁτέοισι φιλεῖς<br>ἀγχοῦ καθῆσθαι. ταῦτα δ᾽ Ἱππῶναξ σκαφεὺς<br>οἶδεν ἄριστα βροτῶν,<br>οἶδεν δὲ κ᾽ Ἀρίφαντος: ἆ μάκαρ ὅτις<br>μήδαμά κως ἔϊδε<br>γράσου πνέοντα φῶρα: τῷ χυτρεῖδ᾽ ὅτε<br>Αἰσχυλίδῃ πολέμει,<br>ἐκεῖνος ἤμερσέν σε παρθενηΐης,<br>πᾶς δὲ πέφηνε λόγος.”<br><em>Pap. Argentorat. Sitz. b. Berl. Akad. 1899. 857<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ τετράμετρον (δακτυλικὸν) εἰς δισύλλαβον καταληκτικόν, ᾧ πρῶτος μὲν ἐχρήσατο Ἀρχίλοχος ἐν Ἐπῳδοῖς:<br>φαινόμενον κακὸν οἴκαδ᾽ ἄγεσθαι<br><em>Heph. 7. 2. p. 21 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ μέλος καὶ στάσεων καὶ ταραχῶν εἷναι καταπαυστικόν ... διὸ καὶ τὸν Ἀρχίλοχον λέγειν:<br>κηλεῖται δ᾽ ὅτις ἔστιν ἀοιδαῖς.<br><em>Philod. Mus. 20 K ...<\/em>"}, {"st": "—", "sp": "N", "t": "“τρίμετρον δὲ καταληκτικὸν (τροχαϊκόν), οἷόν ἐστι τὸ Ἀρχιλόχου, ὅ τινες ἀκέφαλον ἰαμβικὸν καλοῦσι:<br>Ζεῦ πάτερ, γάμον μὲν οὐκ ἐδαις άμην.<br><em>Heph. 6. 2. p. 18<\/em>"}, {"st": "—", "sp": "N", "t": "“ἔστι δὲ ἐν αὐτῷ (τῷ τροχαϊκῷ) ἐπίσημον κα τὸ δίμετρον βραχυκατάληκτον, τὸ καλούμενον ἰθυφαλλικόν: ᾧ πρῶτος μὲν Ἀρχίλοχος κέχρηται, συζεύξας αὐτο δακτυλικῷ τετραμέτρῳ οὕτως:<br>οὐκέθ᾽ ὁμῶς θάλλεις ἁπαλὸν χρόα: κάρφεται γὰρ ἤδη.<br><em>Heph. 6. 3. p. 19<\/em>"}, {"st": "—", "sp": "N", "t": "“Ὁμήρου εἰπόντος(<em>Il. 21. 353<\/em>)’τείροντ᾽ ἐγχέλυές τε καὶ ἰχθύες’ ἀκολούθως ἐποίησε καὶ Ἀρχίλοχος:<br>πολλὰς δὲ τυφλὰς ἐγχέλυας ἐδέξω.<br><em>Ath. 7. 299a ...<\/em>"}, {"st": "—", "sp": "N", "t": "“τὸ γὰρ ἀπτερύονται οἱονεὶ τὰ πτερὰ χαλάσαντες ἀντὶ τοῦ διασείουσι τὰς πρέρυγας ὑποστρέψαντες: διακινοῦσι γὰρ τὰς πτέρυγας ἤτοι ὑφ᾽ ἡδονῆς τὴν κοίτην καταλαβόντες ἢ τὴν ἐκ τοῦ ἀέρος διατινάσσοντες ἰκμάδα. καὶ παρ᾽ Ἀρχιλόχῳ ἡ ὑφ᾽ ἡδονῆς σαλευομένη κορώνη<br>... ὡς κηρύλος<br>πέτρης ἐπὶ προβλῆτος ἀπτερύσσετο.<br><em>Sch. Arat. 1009<\/em>"}, {"st": "—", "sp": "N", "t": "“ψόγος Ἀφροδίτης: καὶ ὅτι φαῦλον ὁ ἔρως καὶ πόσων εἴη κακῶν γεγονὼς αἴτιος: Ἀρχιλόχου:<br>τοῖος γὰρ φιλότητος ἔρως ὑπὸ καρδίην ἐλυσθεὶς<br>πολλὴν κατ᾽ ἀχλὺν ὀμμάτων ἕχευεν,<br>κλέψας ἐκ στηθέων ἁπαλὰς φρένας.<br><em>Stob. Fl. 64. 11<\/em>"}, {"st": "—", "sp": "N", "t": "“καὶ ἔτι ‘εὖτε πρὸς’ κτλ.<br>εὖτε πρὸς ἄεθλα δῆμος ἠθροΐζετο,<br>ἐν δὲ Βατουσιάδης<br><em>Heph. π. ποιημ. 7. 2. p. 71 Cons ... <\/em>“π. καταληκτικῶν: ἐὰν δὲ τρισύλλαβος ᾖ ὁ ποὺς ὁ τὸ μέτρον συνιστάς, δύναται καὶ παρὰ δύο συλλαβὰς εἶναι τὸ καταληκτικόν, οἷον ἐπὶ δακτυλικοῦ ‘ἐν δὲ’ κτλ. ἐνταῦθα γὰρ ἡ δης συλλαβὴ ἀντὶ τρισυλλάβου κεῖται.” <em>Heph. Ench. 4. 2. p. 13 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>Σελληϊάδεω<br>Σελλέως υἱὸς ὁ μάντις Βατουσιάδης τὸ ὄνομα.”<br><em>Hesych.<\/em>"}, {"st": "—", "sp": "N", "t": "“πρόκειται τὰ πράγματ᾽ αὐτοῖς (τοῖς θεοῖς) ὥσπερ ἐν ὀφθαλμοῖς. διὰ τοῦτο ‘Ζεὺς ἐν θεοῖσι’ κτλ., καὶ ὅτι γε δ᾽ αὐτὸ τοῦτο ὁ αὐτὸς οὗτος ποιητὴς μαρτυρεῖ. τὸ γὰρ δεύτερόν ἐστιν αὐτῷ: ‘καὶ τέλος’ κτλ.<br>Ζεὺς ἐν θεοῖσι μάντις ἀψευδέστατος<br>καὶ τέλος αὐτὸς ἔχει.<br><em>Aristid. Or. 2. 51<\/em>"}, {"st": "—", "sp": "N", "t": "“de pentametro iambico catalecto: Hoc potest dividi in dimetrum acatalectum Archilochium, de quo supra docui,<br><em>Mar. Plot. Gr. Lat. 6. 2. 527 K<\/em>"}, {"st": "—", "sp": "N", "t": "“π. περδίκων: τοῦ δὲ ὀνόματος αὐτῶν ἔνιοι συστέλλουσι τὴν μέσην συλλαβήν, ὡς Ἀρχίλοχος:<br>πτώσσουσαν ὥστε πέρδικα<br><em>Ath. 9. 388 f<\/em>"}, {"st": "—", "sp": "N", "t": "“γενναῖα λέγει τὰ εὐγενῆ ὁ φιλόσοφος, ὡς καὶ Ἀρχίλοχος:<br>πάρελθε, γενναῖος γὰρ εἶς.<br><em>Ath. 14. 653 d<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>ναὶ ναὶ μὰ μήκωνος χλόην:<br>ὅρκος ἐπὶ χλευασμῷ.”<br><em>Suid.<\/em>"}, {"st": "—", "sp": "N", "t": "“θῳή: ... ἔχει δὲ τὸ ι ἐκ παραδόσεως, ἐπειδὴ εὕρηται θωϊή, ὡς παρ᾽ Ἀρχιλόχῳ:<br>ὡς δ᾽ ἄν ς ε θωϊὴ λάβοι<br><em>Et. Magn. 26. 23<\/em>"}, {"st": "—", "sp": "N", "t": "“εἴωθε καὶ ὁ Ἀρχίλοχος μελάμπυγον τοῦτον (τὸν ἀετὸν) καλεῖν:<br>μή τευ μελαμπύγου τύχῃς<br><em>Sch. Il. 24. 315<\/em>"}, {"st": "—", "sp": "N", "t": "“ἐμπελάδην, σίνεγγυς, ἤ, ὡς ἔνιοι, χωρίς: καὶ Ἀρχίλοχος ἐπι τοῦ χωρίς:<br>ἔμπλην ἐμοῦ τε καὶ Φόλου<br><em>Apoll. Soph. 67<\/em>"}, {"st": "—", "sp": "N", "t": "“λεωκόρητος: ὁ ἐξωλοθρευμένος: τὸ γὰρ λέως ἐστὶ τελέως: Ἀρχίλοχος:<br>λείως γὰρ οὐδὲν ἐπρόν εο ν.<br><em>Phot. Lex.<\/em>"}, {"st": "—", "sp": "N", "t": "“Θαργήλια: Ἀπόλλωνος ἑορτὴ καὶ ὅλος ὁ μὴν ιερὸς τοῦ θεοῦ: ἐν δὲ τοῖς Θαργηλίοις τὰς ἀπαρχὰς τῶν φυομένων ποιοῦνται καὶ περικομίζουσι: ταῦτα δὲ Θαργήλιά φασιν: καὶ μὴν Θαργηλιών: καὶ τὴν εὐετηρίαν ἐκάλουν Θαργηλόν: καὶ Ἀρχίλοχος:<br>Φησῖν᾽, ἕως φᾷ: νῦν ἄγει Θαργήλια.<br><em>Hesych.<\/em>"}, {"st": "—", "sp": "N", "t": "“κοίρανος ὁ Μιλήσιος ἰδὼν ἁλιέας τῷ δικτύῳ λαβόντας δελφῖνα καὶ μέλλοντας κατακόπτειν, ἀργύριον δοὺς καὶ παραιτησάμενος ἀφῆκεν ἐς τὸ πέλαγος. καὶ μετὰ ταῦτα ναυαγία χρησάμενος περὶ Μύκονον καὶ πάντων ἀπολομένων μόνος μόνος ὑπὸ δελφῖνος ἐσώθη ὁ Κοίρανος. τελευτήσαντος δ᾽ αὐτοῦ γηραιοῦ ἐν τῇ πατρίδι καὶ τῆς ἐκφορᾶς παρὰ τὴν θάλατταν γιγνομένης, κατὰ τύχην ἐν τῷ λιμένι πλῆθος δελφίνων ἐφάνη ἐν τῇ ἡμέρᾳ ἐκείνῃ μικρὸν ἀπωτέρω τῶν ἐκκομιζόντων τὸν Κοίρανον, ὡσεὶ συνεκφερόντων καὶ συγκηδευόντων τὸν ἄνθρωπον.” <em>Phylarch. ap. Ath. 13. 606d<\/em> “κοίρανος ὄνομα, τὸ γένος ἐκ Παρου, δελφίνων τινῶν ἐν Βυζαντίῳ βόλῳ περιπεσόντων καὶ ἑαλωκότων, δοὺς ἀργύριον οἱονεὶ λύτρα τοῖς ἠγρευκόσιν ἀφῆκεν αὐτοὺς ἐλευθέρους, ἀνθ᾽ ὧν τὴν χάριν ἀπείληφεν. ἔπλει γοῦν ποτε πεντηκόντορον ἔχων, ὡς λόγος, Μιλησίους τινὰς ἄγουσαν ἄνδρας, ἐν δὲ τῷ μεταξὺ Νάξου καὶ Πάρου πορθμῷ τῆς νεὼς ἀνατραπείσης καὶτῶν ἄλλων διαφθαρέντων, τὸν Κοίρανον ἔσωσαν δελφῖνες: ὑπὲρ ἧς εἶχον εὐεργεσίας φθάσαντες τὴν ἴσην ἀντιδιδόντες. καὶ ἔνθα ἐξενήξαντο ὀχοῦντες αὐτὸν ἄκρα δείκνυται καὶ ὕπαντρος πέτρα, καὶ καλεῖται ὁ χῶρος Κοιράνειος. χρόνῳ δὲ ὕστερον τεθνεῶτα τόνδε τὸν Κοίρανον θαλάττης πλησίον ἔκαον. εἶτα μέντοι αἰσθόμενοί πόθεν οἱ δελφῖνες ἠθροίσθησαν, ὥσπερ οὖν ἐπὶ τὸ κῆδος ἥκοντες, καὶ ἐς ὅσον ἡ πυρὰ ἐνήκμαζε καομένη, παρέμειναν ὡς φίλῳ φίλος πιστός. εἶτα μέντοι κατασβεσθείσης οἵδε ἀπενήξαντο.” <em>Ael. N.A. 8.3<\/em> “κοίρανος ... Πάριος γὰρ ὢν τὸ γένος ἐν Βυζαντίῳ δελφίνων βόλον, ἐνσχεθέντων σαγήνῃ καὶ κινδυνευόντων κατακοπῆναι, πριάμενος μεθῆκε πάντας. ὀλίγῳ δὲ ὕστερον ἔπλει πεντηκόντορον ἔχων, ὥς φασι, Μιλησίων ἄνδρας ἄγουσαν, ἐν δὲ τῷ μεταξὺ Νάξου καὶ Πάρου πορθμῷ τῆς νεὼς ἀνατραπείσης καὶ τῶν ἄλλων διαφθαρέντων, ἐκεῖνον λέγουσι δελφῖνος ὑποδραμόντος αὐτῷ καὶ ἀνακουφίζοντος ἐξενεχθῆναι τῆς Σικύνθου κατὰ σπήλαιον, ὃ δείκνυται μέχρι νῦν καὶ καλεῖται Κοιράνειον. ἐπὶ τούτῳ δὲ λέγεται ποιῆσαι τὸν Ἀρχίλοχον: Π̔εντήκοντ᾽ ἀνδρῶν᾽ κτλ. ἐπεὶ δὲ ὕστερον ἀποθανόντος αὐτοῦ τὸ σῶμα πλησίον τῆς θαλάττης οἱ προσήκοντες ἔκαον, ἐπεφαίνοντο πολλοὶ δελφῖνες παρὰ τὸν αἰγιαλόν, ὥσπερ ἐπιδεικνύντες ἑαυτοὺς ἥκοντας ἐπὶ τὰς ταφάς, καὶ παραμείναντες ἄχρι οὗ συνετελέσθησαν.” <em>Plut. Soll. An. 36<\/em> “συνγέγραφεν ὁ Δημέας οὐ μόνον περὶ τὴν ἄλλων δό-<br>ξαν ἀλλὰ καὶ τοῦ ποιητοῦ Ἀρχιλόχου τὰς ἀρετὰς καὶ τῆς<br>λαμπρυνομένης εὐσεβίας καὶ τῆς περὶ τὴν Πάρον φιλοπα-<br>τρίας καὶ τῶν ὑπ᾽ αὐτοῦ17 πεπραγμένων ὑπὲρ τῶν Παρί-<br>ων πολλῶν καὶ μεγάλων ἀγαθῶν δέκα βυβλία<br>παρὲκ τοῦ ἀνηγαγωχότος ταῦτα εἰς ἄρχοντας τοὺς<br>ἐτησίους. γέγραφεν δὲ ὁ Δημέας ἕκαστα τῶν πεπραγμέ-<br>νων καὶ γεγραυμένων ὑπὸ Ὰρχιλόχου κατ᾽ ἄρχοντα<br>ἕκαστον: καὶ ἦρκται ἀπὸ ἄρχντος πρῶτον Εὐρέου, ἐφ᾽ οὗ<br>δοκεῖ πεντηκόντορος Μιλησίων πρέσβεις ἀγαγοῦσα<br>καὶ ἀνακομιζομένη ἐπὶ Μιλήτου διαφθαρῆναι ἐν πόρῳ<br>τῷ Ναξιακῷ, καὶ σωθῆναι ἕνα τινὰ αὐτῶν, ᾧ τὸ ὄνομα Κοίρα-<br>νος, ὑπὸ δελφῖνος ἀναλημφθέντα, καὶ ἐκπεσόντα ἐπὶ τὰ<br>Ἐπισυρίων παράκτια εἴς τι σπήλαιον, σὺν φύλακι ἐαθῆναι<br>ἐκεῖθεν ἀθῷον κατὰ πρεσβευτησίαν. τὸ δὲ σπήλαιον τοῦτο<br>ἔτι νῦν ἱερὸν ἔχομεν, καὶ ἀπ᾽ αὐτοῦ Κοιράνειον καλεῖται.<br>καὶ ἀπῴκισε μετ᾽ Ἀρχιλόχου ὁ Κοίρανος ἐν τῷ δευτέρῳ<br>ἀποικισμῷ τῆς Θάσου καὶ ἐν τῷ πολέμῳ, οὗ μνήμην ποιεῖ-<br>ται ὁ Ἀρχίλοχος τήνδε:<br>πεντήκοντ᾽ ἀνδρῶν λίπε Κοίρανονͅ ἤπιος Ποσειδῶν<br>ναυαγίας σωθέντ᾽ ἕνα,<br>ὅς τ᾽ ἐλαχυ?ͅπτέρυγον δελφῖν᾽18 ἐκελήτισ᾽ εἰς Σίκυνθον."}, {"st": "—", "sp": "N", "t": "<em>Inscr. Gr. 12. 5. 445 + p. 315<\/em>20<em>, A Col. 1<\/em><br>“ ... χρυσὸν δὲ τέμνοντας ἢ<br>φέροντας τοὺς Θρᾶκας ἂν στερῶσιν Πάριοι, πάντα πάλιν<br>ἀποκαταστήσασθαι αὐτοῖς. διασαφεῖ δὲ ταῦτα πάν-<br>τα οὕτως ὁ Ἀρχίλοχος σκώπτων ὅτι ἐψευδόρκησαν:<br>τόλμαν ἐκπρέπουσαν εἶδεν, εἴ τις ἦν ἀναιβάτης,<br>ἀνͅγράφη τ᾽ ἔτης Ἀρῇος Ἐξακεστομαλκιδῶν:<br>ὡς φάα χροͅὶ προσίζει, τὼς22 ὁ παῖς Πεισιστράτου<br>ἄνδρας εὖ ι νωμῶντας αὐλὸν καὶ λύρην ἀνῆρ᾽23 ἄγων<br>εἰς Θάσον, φωσὶ ι Θρέϊξιν δῶρ᾽ ἔχων ἀκήρατον<br>χρυσόν: οἰκείῳ δὲ κέρδει ξύν᾽ ἐποίησαν κακά.<br>τοὺς Θρᾷκας<br>ἀποκτείναντες αὐτοὶ οἱ μὲν αὐτῶν ὑπὸ Παρίων<br>ἀπεπνίχησαν, οἱ δὲ δρῆσται ἀπάχθησαν ὑπὸ τῶν Θραχͅ-<br>κῶν. μετὰ ταῦτὰ πάλιν γίνεται ἄρχων Ἀμ-<br>φίτιμος, καὶ ἐν τούτοις διασαφεῖ πάλιν ὡς<br>ἐνίκησαν καρτέρως τοὺς Ναξίους, λέγων<br>οὕτω:<br>τῶν δ᾽ ἀνωτάτη Τύχη<br>ἵλαος παρασταθεῖσα ι φᾶ τ᾽ ἔβαινέ θ᾽, ᾗ τ᾽ ἴῃ<br>ἄρχεν, ἦν τ᾽ αἴειν ἀϋτῆς τῆς πολυ ι τλαντος λεώ:<br>κοὔτις ἦν τῶν ῥιψακόντων ωὑκ24 ἐφημμένη σερίς,<br>ἀλλ᾽ ἀκόντισαν: τόσοι τ᾽ ἄρ᾽ ἀθρόοις ἐξάλμασι<br>τῆλ᾽ ἐͅπέκθεον, τόσ᾽ ἔλλαβ᾽ Ἀΐδης ἑλώρια.<br>ὅν τ᾽ ... ι<br><em>4.<\/em><br>“ὥς φησιν ὁ<br>Δημέας, ἀλλὰ ἐνίκησαν: ὅτι δ᾽ ἀληθῆ λέγει<br>δηλοῖ ὁ ποιητὴς οὕτω:<br>Τροπαῖον ἕστηκ᾽: εὐφρόνη ι δ᾽ ἐπὶ στρατὸν<br>ἦλθ᾽, οὐδὲ χείρον᾽ ὧν ἐόλπεμεν τὰ ι νῦν<br>ἐεργμέν᾽, ἀλλὰ τῆσδε γῆς κρατήσατε<br>ὅͅπη μ᾽ ἔσωσε ῥαχίης Ποσειδέων,<br>οὗ χωρὶς οὐκ ἂν τέͅμενος ἀλλ᾽ ἀνωφελῆ<br>γῆν εἴχεθ᾽ οἵας μὴ θεοὶ συνοικέͅται.<br> <br>ὅτι δὲ Γλαῦκος τὸν στρατηγὸν τῶν Θρᾳκῶν (̣) μονα-<br>χὸν μάχῃ κρατήσας ἀπέκτεινεν, ὥς φησιν ὁ Δημέας,<br>δηλοῖ ὁ ποιητὴς διὰ τῶν ἰάμβων οὕτω:<br>Γλαῦκ᾽, οὐ σὺ γυι̂ͅον καὶ φρένας τρέσεις ἰὼν<br>ἐς ὄψιν Ἀρέως: οὐ γὰρ ἦσθα τἆρ᾽ ὅτις<br>σῆς ι γῆς ἐπιμνήσαιο ῥᾳθυμῶν μόνον,<br>ἢ παρὰ πότον τὰ δειͅνὰ τολμήσας μέθῃ<br>Ἄρει τραπείης νῶτον: ἀλλ᾽ ἡγήτορα<br>ἀνεῖλες αἰχμῇ, καὶ μόνος μαχεύμενος<br>πολλῶν κρατεῖς:ισὸν δ᾽ ἔσκε καὶ χόλῳ φοβεῖν.<br> <br>ἐκδημία δ᾽ ἦν αὐτῷ οὐδεμία<br>εἰ μὴ οἱ εἰς τὴν Θάσον πλοῖ, οὓς ἔπλευσε πολλούς, φοι-<br>τήσας καὶ παρ᾽ ἑταίραν τινὰ θυγατέρα οὖσαν ταύτης<br>τῆς γαύρας ᾗτινι ὀνειδίζει διὰ τῶν ἰάμβων οὕτω:<br>πῶς δὴ τοιαῦτα βήσομ᾽ ἀγκαλίσματα;<br>οὐ σῦχ᾽ ἕλωμαι πρόͅτερον ἀχραδινέων;<br>ὡς δ᾽ ὁ Δημέας φησί, συνήγαγεν ἀπι-<br>ὼν τῆς Θάσου καὶ δάμαρτι ἐχρήσθη αὐτῇ καὶ οὐ παλ-<br>λακῇ: ὅτι δ᾽ ἀληθῆ λέγει ὁ Δημέας ταῦτα γράφων<br>ὑπὲρ ταύτης τῆς παλλακῆς, δηλοῖ ὁ Ἀρχίλοχος παρὰ<br>τάδε:<br>χιλίους γὰρ ἄνδρας εἶχες, ἥτις ἄνδρ᾽ ἔχεις ἕνα.<br>καὶ<br>ταῦτα:<br>γυναῖκά σ᾽ εἷλον γαμέτιν, ἧς λεωφόρου<br>τύχησα, ι ταῖς μαίαισι δ᾽ ἧς τέξαις γονῆς<br>πιστός τις ὢν πέφηνα ι παιδαναιρέτης.<br>ι μετὰ δ᾽ ἑπτὰ ἔτη, ὥς φησι Δημέας, διέ-<br>στησαν: ὅτι δ᾽ ἀληθῆ λέγει, δηλοῖ ὁ ποιητὴς λέγων<br>τάδ᾽:<br>Ἔτεξας, ὦ Τέρεινα, τὴν ἐγὼ θορὴν<br>ἔν σοι γάμῳ φύτευͅς α παραφερνησίω:<br>καὶ παρὰ τάδε:<br>Ἣν πρόσφατον ποίη?ͅς α τεταριχευμένην<br>τοὔμπροσθε κέρκῳ μυͅρίᾳ Καβαρνίδι,<br>ἀκήρατος συνῶρος ἑπτὰ ταῦτ᾽ ἔτη ι<br>ἔχω μίαν γυναῖκά σ᾽: ἀλλ᾽ ὡρᾳζέαι<br>διαφρονεῦσα, καὶ ι κασαλβάδας δέκα<br>ἀπ εό ντι δώμαθ᾽ ἵκἐ εἰσάγουσά ι μοι.<br>μεταμφίευ δὲ κἄξιθι πρὸς ἑσπέραν,<br>καὶ ι κῶλ᾽ ἀρεῦ βινεῦσιν ᾐθέοις πάλιν.<br>ι καὶ ταῦτα:<br>πῆ βήσεαι νέορτον ἐπι γαμέειν πόσιν;<br>τίθει δ᾽ ὀͅχῇα βατράχῳ Σεριφίω:<br>κᾆτ᾽ εὐπορήσεις διψέουσ᾽, ἐὰν ι δ᾽ ἄρα<br>βινητιήσῃς, στριφνὰ βινηθήσεαι:<br>ὡς δέ φησιν ὁ Δη-<br>μέας, ἐπ᾽ Ἀκραιφνίοις ἐστρατεύσαντο εὐτυχῶς: ὡς<br>δὲ ἀληθῆ ἅ φησιν, ὁ Ἀρχίλοχος διασαφεῖ σκωπτων πα-<br>ρὰ τάδε:<br>Ἀκραιφνί, πῶς ἔχεις σὺ τῶν πολιτέων;<br>ἕκα-<br>στα δὲ ταῦτα διασαφεῖ ὅτι ἀληθῆ ἐστιν ὁ ποιητὴς<br>παρὰ τάδε:<br>ἐπεὶ τὰ δεινὰ μηδὲν ἠγνόευν ἔτι,<br>σαγῶν ι ἀγόρασαν ἄλφιτα, ξύρης α δὲ<br>τμήξας ἀπ᾽ ἴτυος ι ὄχμ᾽, ἵνα στύφω δέρας<br>τἠμῇ γυναικὶ γηραῶν μυρͅμηκιῶν<br>μηδ᾽ ἀμπέχω καρῖδα (̣):<br>καὶ τάδε:<br>Ἐπεὶ δὲ ι χειρῶν δούρατ᾽ ἔκπαλλον, κρέων<br>γαύροις λόγοις ι ὤρινε: τῶν δ᾽ ἐδάμνατο<br>ὕβρις: πέλας γὰρ στᾶσ᾽ ι ἀθηναίη διὸς<br>ἀμφ᾽ ἧμιν ὕψι νεῦσεν, Αἰολεῖς δ᾽ ἄρα ι<br>θέσαν πρόχουν τριγχοῖσι, κοὐκ Ἰάονες.<br>ἐπεὶ δ᾽ ἐͅρηκτο πύργος ἀμφαδήν27 σφισιν,<br>ὃν Κᾶρες ἦραν θέσεϊͅ βαρδίστῃ28 λίθων<br>ἱδρῶντες, ἡμῖν ἠπύη29 πάσας ἀνα<br>φυͅ λὰς ἄορτο Λεσβίων φορμιγκτέων,<br>χεῖρας δὲͅ θέντες χερσὶν ὀρχεῦντο στρατός:<br>κἀπεκτύπῃσε Ζεὺς Ὀλυμπίων πατήρ.<br>τῶν δ᾽ οὔτις ἐς τὸ λοιͅπὸν ἦν ἐπήβολος<br>τῶν πρόσθεν εἶχ᾽, ἀλλ᾽ͅ ἕστασαν πονεύμενοι<br>καὶ σφέας ἀποσβεῖσ᾽ͅ ἔφθαν᾽ ἣν ἀμφράσσατο<br>ἕκαστος ἐλπὶς οὐ πάλινͅ φανευμένη,<br>καθήμενοι δ᾽ ἄβριγδα τήρεον φάος.<br><em>Col. 4<\/em><br>“ ... Ἀπολλώνιο ... <br>... τῆς<br>μητρὸς αὐτῆς ... ... <br>καὶ μετὰ̣ ... ... <br>... .<br>... τῆς πατρίδος καὶ Ἀρχιλόχου ἐνταῦθα πάλιν<br>μέμνηται ὁ Δημέας (̣) ... ...<br>τίς σε τὸν ἐν πέτρῃ Μουσῶν θεράποντ᾽ ἐχάραξεν<br>παῖ Τελεσικλῆος κοῦρε καταγλαΐσας;<br>λέξω δή σοι ἐγὼ μάλ᾽ ἐτήτυμα, εἰ σὺ μὴ οἶδας:<br>ἐσθλὸς ἐὼν ἀρετῆς τ᾽ οὐκ ὑπολειπόμενος<br>Σωσθεὺς Προσθένου υἱὸς ἐμὴν πολύυμνον ἀοιδὴν<br>τιμῶν ἀενάων αἶσαν ὑπεσπάσατο.<br>... 30<br><em>B Col. 4<\/em>"}, {"st": "—", "sp": "N", "t": "“π. ἀσυναρτήτων: γίνεται δὲ ὁ τελευταῖος τῆς τετραποδίας διὰ τὴν ἐπὶ τέλους ἀδιάφορον καὶ κρητικός:<br>καὶ βήσσας ὀρέων δυσπαιπάλους οἷος ἦν ἐπ ἥβης<br><em>Heph. 15. 8. p. 50 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“π. ἰαμβικοῦ καταληκτικοῦ: τρίμετρον δὲ οἷον τὸ Ἀρχιλόχου:<br>ὄγμος, κακοῦ δὲ γήραος καθαιρεῖ<br><em>Heph. 5.3. p. 16<\/em>"}, {"st": "—", "sp": "N", "t": "“πάρος: νῆσος, ἣν καὶ<br>πόλιν<br>Ἀρχίλοχος καλεῖ ἐν τοῖς Ἐπῳδοῖς.”<br><em>Steph. Byz.<\/em>"}, {"st": "—", "sp": "N", "t": "“<br>πόλλ᾽ οἶδ ἀλώπηξ, ἀλλ᾽ ἐχῖνος ἓν μέγα.<br>μέμνηται ταύτης Ἀρχίλοχος ἐν ἐπῳδῇ ... λέγεται δὲ ἡ παροιμία ἐπὶ τῶν πανουργοτάτων.”<br><em>Zenob. 5. 68<\/em>"}, {"st": "—", "sp": "HDR", "t": "Hymns"}, {"st": "—", "sp": "N", "t": "“ τὸ μὲν Ἀρχιλόχου μέλος<br>φωνᾶεν Ὀλυμπία<br>καλλίνικος ὁ τριπλόος κεχλαδὼς<br>ἄρκεσε Κρόνιον παρ᾽ ὄχθον<br>ἁγεμονεῦσαι κωμάζοντι φίλοις Ἐφαρ-<br>μόστῳ σὺν ἑταίροις:<br>ἀλλὰ νῦν, κτλ.<br>τήνελλα καλλίνικε,<br>χαῖρ᾽ ἄναξ Ἡράκλεες,<br>αὐτός τε κα ὶἸόλαος, αἰχμητὰ δύο.<br>τήνελλα καλλίνικε<br>χαῖρ᾽ ἄναξ Ἡράκλεες.<br><em>Pind. Ol. 9<\/em><br>“(ά) ... ἔθος δὲ ἦν κωμάζειν τὴν νίην τοῖς νικηφόροις μετ᾽ αὐλητοῦ: μὴ παρόντος δὲ αὐλητοῦ εἶς τῶν ἑταίρων ἀνακρουόμενος ἔλεγε: τ̔ήνελλα καλλίνικε.’ — (β́) τὸ μὲν Ἀρχιλόχου μέλος, ὃ τοῖς νικῶσι τὰ Ὀλύμπια ἐπῄδετο, ἦν τρίστροφον, κοινῶς δυνάμενον ἁρμόζειν ἐπὶ παντὸς νικηφόρου διὰ τὸ κατὰ τῆς πράξεως αὐτῆς ψιλὸν ἔχειν τὸν λόγον, μήτε δὲ ὄνομα μήτε ἰδίωμα ἀγωνίσματος. ἐφυμνίῳ δὲ κατεχρῶντο τούτω: ‘ τήνελλα καλλίνικε’ ... — (γ́) τὸ δὲ τριπλόος ὅτι τρὶς ἐπεκελάδουν τὸ καλλίνικε. οὐ καθόλου δὲ τρίς, ἀλλ᾽ ὅτι τριπλῆν ἔχει τὴν στροφὴν καὶ πάλιν ἀναλαμβάμεται. Ἐρατοσθένης δέ φησι μὴ ἐπινίκιον εἶναι τὸ Ἀρχιλόχου μέλος, ἀλλ᾽ ὕμνον εἰς Ἡρακλέα: τρίπλοον δὲ οὐ διὰ τὸ ἐκ τριῶν στροφῶν συγκεῖσθαι, ἀλλὰ διὰ τὸ τρὶς ἐφυμνιάζεσθαι τὸ καλλίνικε. περὶ δὲ τοῦ τήνελλα Ἐρατοσθένης φησὶν ὅτι ὅτε ὁ αὐλητὴς ἢ ὁ κιθαριστὴς μὴ παρῆν, ὁ ἔξαρχος αὐτὸ μεταλαβὼν ἔλεγεν ἔξω τοῦ μέλους, ὁ δὲ τῶν κωμαστῶν χορὸς ἐπέβαλλε τὸ καλλίνικε, καὶ οὕτω συνειρόμενον γέγονε τὸ `τήνελλα καλλίνικε.᾿ ἡ δὲ ἀρχὴ τοῦ μέλους ἐστίν: `ὦ καλλίνικἐ κτλ. — (δ́) Ἀρχίλοχος τῶ Ἡρακλεῖ ὕμνον ποιήσας, ἀπορήσας κιθαρωδοῦ διά τινος λέξεως τὸ μέλος ἐμιμήσατο. συντάξας οὖν τοῦτο τὸ κόμμα τήνελλα, οὕτως τὰ ἑξῆς ἀνεβάλλετο, καὶ αὐτὸς μὲν τὸ μέλος τῆς κιθάρας ἐν μέσω τῷ χορῷ ἔλεγε, τὸ τήνελλα, ὁ δὲ χορὸς τὰ ἐπίλοιπα. ἐκ τούτου τὸ λοιπὸν οἱ ἀποροῦντες κιθαρῳδῶν τούτω τῷ κόμματι ἐχρῶντο τῷ τήνελλα. τὸ δὲ ὅλον οὕτως: `τήνελλἀ κτλ.” <em>Sch. Pind. Ol. 9<\/em> “ἀλαλαλαὶ ἰὴ Παιών, ι τήνελλα καλλίνικος, ὦ ιδαιμόνων ὑπέρτατε.” <em>Ar. Au. 1764<\/em> “τὸ τήνελλα μίμησίς ἐστι φωνῆς κρούματος αὐλοῦ ποιᾶς ἀπὸ τοῦ ἐφυμνίου οὗ εἶπεν ‘Ἀρχίλοχος εἰς τὸν Ἡρακλέα μετὰ τὸν ἆθλον Αὐγέου, `τήνελλἀ κτλ. δοκεῖ δὲ πρῶτος Ἀρχίλοχος νικήσας ἐν Πάρω τὸν Δήμητρος ὕμνον ἑαυτῷ τοῦτον ἐπιπεφωνηκέναι.” <em>Sch. Ar. Au. 1764<\/em>"}, {"st": "—", "sp": "HDR", "t": "Iobacchi"}, {"st": "—", "sp": "N", "t": "“ἄλλο ἀσυνάρτητον ὁμοίως κατὰ τὴν πρώτην ἀντιπάθειαν ἐξ ἰαμβικοῦ διμέτρου ἀκαταλήκτου καὶ τροχαϊκου ἑφθημιμεροῦς, τοῦ καλουμένου Εὐριπιδείου, οἷον τὸ ἐν τοῖς ἀναφερομένοις εἰς Ἀρχίλοχον Ἰοβάκχοις:<br>Δήμητρος ἁγνῆς καὶ Κόρης τὴν πανήγυριν σέβων<br><em>Heph. 15. 16. p. 52 Cons.<\/em>"}, {"st": "—", "sp": "N", "t": "“Βέχειρ ...<br>χρυσοέθειρ<br>παρ᾽ Ἀρχιλόχῳ ἐν Ἰοβάκχοις, ὅπερ ἀποκέκοπται τοῦ χρυσοέθειρος.”<br><em>Steph. Byz.<\/em>"}],[]);})();